string StringPrintf(const char* format, ...) {
  va_list ap;
  va_start(ap, format);
  char buf[4096];
  int n = vsnprintf(buf, sizeof(buf), format, ap);
  va_end(ap);
  if (n >= 0 && (size_t)n < sizeof(buf))
    return string(buf, n);

  // Retry with a dynamically sized buffer.
  va_start(ap, format);
  char* big = NULL;
  n = vsnprintf(NULL, 0, format, ap);
  va_end(ap);
  if (n < 0)
    return string();
  big = (char*)malloc(n + 1);
  va_start(ap, format);
  vsnprintf(big, n + 1, format, ap);
  va_end(ap);
  string ret(big, n);
  free(big);
  return ret;
}

bool ReadFile(const string& path, string* contents, string* err) {
  FILE* fp = fopen(path.c_str(), "rb");
  if (!fp) {
    *err = strerror(errno);
    return false;
  }
  char buf[65536];
  size_t len;
  while ((len = fread(buf, 1, sizeof(buf), fp)) > 0)
    contents->append(buf, len);
  if (ferror(fp)) {
    *err = strerror(errno);
    fclose(fp);
    return false;
  }
  fclose(fp);
  return true;
}

string TrimTrailingWhitespace(const string& s) {
  size_t end = s.size();
  while (end > 0 && (s[end - 1] == '\n' || s[end - 1] == '\r'))
    --end;
  return s.substr(0, end);
}

void CanonicalizePath(string* path) {
  size_t len = path->size();
  if (len == 0)
    return;
  // Work in a scratch buffer.
  vector<char> buf(len);
  char* prefix = &buf[0];
  char* suffix = prefix + len;
  // Points at the start of the last path component.
  char* last = prefix;
  const char* p = path->c_str();
  const char* end = p + len;
  bool has_leading_slash = false;
  if (*p == '/') {
    has_leading_slash = true;
    ++p;
  }
  while (p < end) {
    // Skip slashes.
    while (p < end && *p == '/')
      ++p;
    if (p == end)
      break;
    // Read a component.
    const char* start = p;
    while (p < end && *p != '/')
      ++p;
    size_t comp_len = p - start;
    if (comp_len == 1 && start[0] == '.') {
      continue;
    } else if (comp_len == 2 && start[0] == '.' && start[1] == '.') {
      if (last != prefix) {
        // Remove the previous component.
        --last;
        while (last > prefix && last[-1] != '/')
          --last;
      }
      continue;
    }
    if (last != prefix)
      *last++ = '/';
    memcpy(last, start, comp_len);
    last += comp_len;
  }
  if (last == prefix) {
    *path = has_leading_slash ? "/" : ".";
    return;
  }
  string out;
  if (has_leading_slash)
    out.push_back('/');
  out.append(prefix, last - prefix);
  *path = out;
}

string ShellEscape(const string& in) {
  // Do not escape if the string only contains safe characters.
  static const char kSafe[] = "abcdefghijklmnopqrstuvwxyz"
                              "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_.+/";
  bool need_escape = false;
  for (size_t i = 0; i < in.size(); ++i) {
    if (strchr(kSafe, in[i]) == NULL) {
      need_escape = true;
      break;
    }
  }
  if (!need_escape)
    return in;
  string out;
  out.push_back('\'');
  for (size_t i = 0; i < in.size(); ++i) {
    if (in[i] == '\'') {
      out += "'\\''";
    } else {
      out.push_back(in[i]);
    }
  }
  out.push_back('\'');
  return out;
}

int EditDistance(const string& a, const string& b, int max_distance) {
  // Trim the common prefix and suffix.
  size_t i = 0;
  while (i < a.size() && i < b.size() && a[i] == b[i])
    ++i;
  size_t j = 0;
  while (j < a.size() - i && j < b.size() - i &&
         a[a.size() - 1 - j] == b[b.size() - 1 - j])
    ++j;
  string aa = a.substr(i, a.size() - i - j);
  string bb = b.substr(i, b.size() - i - j);
  size_t alen = aa.size(), blen = bb.size();
  if (alen > (size_t)max_distance || blen > (size_t)max_distance)
    return max_distance + 1;
  // Use two rows of the DP table.
  vector<int> prev(blen + 1), cur(blen + 1);
  for (size_t k = 0; k <= blen; ++k)
    prev[k] = (int)k;
  for (size_t x = 1; x <= alen; ++x) {
    cur[0] = (int)x;
    int best = cur[0];
    for (size_t y = 1; y <= blen; ++y) {
      int cost = (aa[x - 1] == bb[y - 1]) ? 0 : 1;
      int v = prev[y - 1] + cost;
      if (prev[y] + 1 < v) v = prev[y] + 1;
      if (cur[y - 1] + 1 < v) v = cur[y - 1] + 1;
      cur[y] = v;
      if (v < best) best = v;
    }
    if (best > max_distance)
      return max_distance + 1;
    prev.swap(cur);
  }
  int result = prev[blen];
  if (result > max_distance)
    return max_distance + 1;
  return result;
}

int64_t GetTimeNanos() {
  struct timespec ts;
  clock_gettime(CLOCK_REALTIME, &ts);
  return (int64_t)ts.tv_sec * 1000000000LL + ts.tv_nsec;
}

int64_t GetTimeMillis() {
  return GetTimeNanos() / 1000000;
}

double GetTimeSeconds(int64_t start_time) {
  return (GetTimeMillis() - start_time) / 1000.0;
}

string FormatDuration(int64_t ms) {
  int64_t seconds = ms / 1000;
  int64_t minutes = seconds / 60;
  seconds %= 60;
  int64_t hours = minutes / 60;
  minutes %= 60;
  if (hours > 0)
    return StringPrintf("%d:%02d:%02d", (int)hours, (int)minutes, (int)seconds);
  return StringPrintf("%02d:%02d", (int)minutes, (int)seconds);
}

vector<string> Split(const string& str, char sep) {
  vector<string> out;
  size_t start = 0;
  for (size_t i = 0; i <= str.size(); ++i) {
    if (i == str.size() || str[i] == sep) {
      out.push_back(str.substr(start, i - start));
      start = i + 1;
    }
  }
  return out;
}
