string StringPrintf(const char* format, ...) {
  va_list ap;
  va_start(ap, format);
  char buf[4096];
  int n = vsnprintf(buf, sizeof(buf), format, ap);
  va_end(ap);
  if (n >= 0 && (size_t)n < sizeof(buf))
    return string(buf, n);

  // Retry with a dynamically sized buffer.
  va_start(ap, format);
