  n = vsnprintf(NULL, 0, format, ap);
  va_end(ap);
  if (n < 0)
    return string();
  big = (char*)malloc(n + 1);
  va_start(ap, format);
  vsnprintf(big, n + 1, format, ap);
  va_end(ap);
  string ret(big, n);
  free(big);
  return ret;
}

