  if (!fp) {
    *err = strerror(errno);
    return false;
  }
  char buf[65536];
  size_t len;
  while ((len = fread(buf, 1, sizeof(buf), fp)) > 0)
    contents->append(buf, len);
  if (ferror(fp)) {
    *err = strerror(errno);
    fclose(fp);
    return false;
  }
  fclose(fp);
  return true;
}

