    --end;
  return s.substr(0, end);
}

void CanonicalizePath(string* path) {
  size_t len = path->size();
  if (len == 0)
    return;
  // Work in a scratch buffer.
  vector<char> buf(len);
  char* prefix = &buf[0];
  char* suffix = prefix + len;
  // Points at the start of the last path component.
  char* last = prefix;
  const char* p = path->c_str();
  const char* end = p + len;
  bool has_leading_slash = false;
  if (*p == '/') {
    has_leading_slash = true;
    ++p;
  }
  while (p < end) {
    // Skip slashes.
    while (p < end && *p == '/')
      ++p;
    if (p == end)
      break;
    // Read a component.
    const char* start = p;
    while (p < end && *p != '/')
      ++p;
    size_t comp_len = p - start;
    if (comp_len == 1 && start[0] == '.') {
      continue;
    } else if (comp_len == 2 && start[0] == '.' && start[1] == '.') {
      if (last != prefix) {
        // Remove the previous component.
        --last;
        while (last > prefix && last[-1] != '/')
          --last;
      }
      continue;
    }
    if (last != prefix)
      *last++ = '/';
    memcpy(last, start, comp_len);
    last += comp_len;
  }
  if (last == prefix) {
    *path = has_leading_slash ? "/" : ".";
    return;
  }
  string out;
  if (has_leading_slash)
    out.push_back('/');
  out.append(prefix, last - prefix);
  *path = out;
}

string ShellEscape(const string& in) {
  // Do not escape if the string only contains safe characters.
  static const char kSafe[] = "abcdefghijklmnopqrstuvwxyz"
