  bool need_escape = false;
  for (size_t i = 0; i < in.size(); ++i) {
    if (strchr(kSafe, in[i]) == NULL) {
      need_escape = true;
      break;
    }
  }
  if (!need_escape)
    return in;
  string out;
  out.push_back('\'');
  for (size_t i = 0; i < in.size(); ++i) {
    if (in[i] == '\'') {
      out += "'\\''";
    } else {
      out.push_back(in[i]);
    }
  }
  out.push_back('\'');
  return out;
}

int EditDistance(const string& a, const string& b, int max_distance) {
  // Trim the common prefix and suffix.
  size_t i = 0;
  while (i < a.size() && i < b.size() && a[i] == b[i])
    ++i;
  size_t j = 0;
  while (j < a.size() - i && j < b.size() - i &&
         a[a.size() - 1 - j] == b[b.size() - 1 - j])
    ++j;
  string aa = a.substr(i, a.size() - i - j);
  string bb = b.substr(i, b.size() - i - j);
  size_t alen = aa.size(), blen = bb.size();
  if (alen > (size_t)max_distance || blen > (size_t)max_distance)
    return max_distance + 1;
  // Use two rows of the DP table.
  vector<int> prev(blen + 1), cur(blen + 1);
  for (size_t k = 0; k <= blen; ++k)
    prev[k] = (int)k;
  for (size_t x = 1; x <= alen; ++x) {
    cur[0] = (int)x;
    int best = cur[0];
    for (size_t y = 1; y <= blen; ++y) {
      int cost = (aa[x - 1] == bb[y - 1]) ? 0 : 1;
      int v = prev[y - 1] + cost;
      if (prev[y] + 1 < v) v = prev[y] + 1;
      if (cur[y - 1] + 1 < v) v = cur[y - 1] + 1;
      cur[y] = v;
      if (v < best) best = v;
    }
    if (best > max_distance)
      return max_distance + 1;
    prev.swap(cur);
  }
  int result = prev[blen];
  if (result > max_distance)
    return max_distance + 1;
  return result;
}

