}

int64_t GetTimeMillis() {
  return GetTimeNanos() / 1000000;
}

double GetTimeSeconds(int64_t start_time) {
  return (GetTimeMillis() - start_time) / 1000.0;
}

string FormatDuration(int64_t ms) {
