    PIPE2,
    PIPEAT,
    EQUALS,
    EOF_TOKEN,
  };

  Lexer() : input_(NULL), pos_(NULL), marker_(NULL), filename_("") {}
  Lexer(const string& filename, const string& input)
      : input_(input.data()), pos_(input.data()), marker_(input.data()),
        end_(input.data() + input.size()), filename_(filename) {}

  void Start(const string& filename, const string& input) {
    input_ = input.data();
    pos_ = input.data();
    marker_ = input.data();
    end_ = input.data() + input.size();
    filename_ = filename;
  }

