// Lexer for the ninja build file format.
#ifndef NINJA_LEXER_H_
#define NINJA_LEXER_H_

#include <string>
using namespace std;

struct Lexer {
  enum Token {
    UNKNOWN,
    NEWLINE,
    INDENT,
    IDENT,
    COLON,
    PIPE,
    PIPE2,
    PIPEAT,
    EQUALS,
    EOF_TOKEN,
  };

  Lexer() : input_(0), pos_(0), end_(0), filename_("") {}
  Lexer(const string& filename, const string& input) { Start(filename, input); }

  void Start(const string& filename, const string& input);

  /// Report an error message with the current position, including the
  /// offending source line and a caret.
  bool Error(const string& message, string* err);
  /// Report an error message with the current position, but without the
  /// source context (the message is terminated by a newline instead).
  bool ErrorNoContext(const string& message, string* err);

  Token ReadToken();
  Token PeekToken();
  bool PeekToken(Token token);

  const char* TokenName(Token token) const;

  bool ReadIdent(string* out);
  bool ReadPath(string* out, string* err);
  bool ReadValue(string* out, string* err);

  /// Return the name of the token that is currently being read, for error
  /// messages that point at a token that was already consumed.
  int GetLine() const;
  const char* GetPos() const { return pos_; }
  void SetPos(const char* p) { pos_ = p; }
  const string& GetFilename() const { return filename_; }
  int LineFor(const char* pos) const;
  /// Position of the start of the line containing pos.
  const char* LineStartFor(const char* pos) const;
  bool AtLineStart() const;

 private:
  const char* input_;
  const char* pos_;
  const char* end_;
  string filename_;
};
#endif  // NINJA_LEXER_H_
