#include "lexer.h"
#include "util.h"

#include <ctype.h>
#include <string.h>

void Lexer::Start(const string& filename, const string& input) {
  input_ = input.data();
  pos_ = input.data();
  end_ = input.data() + input.size();
  filename_ = filename;
}

int Lexer::LineFor(const char* pos) const {
  int line = 1;
  for (const char* p = input_; p < pos; ++p)
    if (*p == '\n')
      ++line;
  return line;
}

const char* Lexer::LineStartFor(const char* pos) const {
  const char* p = pos;
  while (p > input_ && p[-1] != '\n')
    --p;
  return p;
}

bool Lexer::AtLineStart() const {
  return pos_ == input_ || pos_[-1] == '\n';
}

bool Lexer::Error(const string& message, string* err) {
  const char* line_start = LineStartFor(pos_);
  const char* line_end = pos_;
  while (line_end < end_ && *line_end != '\n')
    ++line_end;
  string line_text(line_start, line_end);
  int col = (int)(pos_ - line_start);
  string caret;
  for (int i = 0; i < col; ++i)
    caret.push_back(' ');
  *err = StringPrintf("%s:%d: %s\n%s\n%s^ near here", filename_.c_str(),
                      LineFor(pos_), message.c_str(), line_text.c_str(),
                      caret.c_str());
  return false;
}

bool Lexer::ErrorNoContext(const string& message, string* err) {
  *err = StringPrintf("%s:%d: %s\n", filename_.c_str(), LineFor(pos_),
                      message.c_str());
  return false;
}

const char* Lexer::TokenName(Token token) const {
  switch (token) {
    case NEWLINE: return "newline";
    case INDENT: return "indent";
    case IDENT: return "identifier";
    case COLON: return "':'";
    case PIPE: return "'|'";
    case PIPE2: return "'||'";
    case PIPEAT: return "'|@'";
    case EQUALS: return "'='";
    case EOF_TOKEN: return "eof";
    default: return "lexing error";
  }
}

Lexer::Token Lexer::ReadToken() {
  for (;;) {
    if (pos_ >= end_)
      return EOF_TOKEN;
    // At the beginning of a line, leading whitespace introduces an
    // indentation token.
    if (AtLineStart() && *pos_ == ' ') {
      const char* p = pos_;
      while (p < end_ && (*p == ' ' || *p == '\t'))
        ++p;
      if (p < end_ && *p == '\n') {
        // A blank line: not an indent.
        pos_ = p;
        continue;
      }
      if (p < end_ && *p == '#') {
        // A comment line: skip it entirely, including the newline.
        while (p < end_ && *p != '\n')
          ++p;
        if (p < end_)
          ++p;
        pos_ = p;
        continue;
      }
      pos_ = p;
      return INDENT;
    }
    char c = *pos_;
    switch (c) {
      case ' ':
      case '\t':
      case '\r':
        ++pos_;
        continue;
      case '\n':
        ++pos_;
        return NEWLINE;
      case '#':
        // Comments are only recognized at the start of a line.
        if (AtLineStart()) {
          while (pos_ < end_ && *pos_ != '\n')
            ++pos_;
          if (pos_ < end_)
            ++pos_;
          continue;
        }
        return UNKNOWN;
      case '=':
        ++pos_;
        return EQUALS;
      case ':':
        ++pos_;
        return COLON;
      case '|':
        ++pos_;
        if (pos_ < end_ && *pos_ == '|') {
          ++pos_;
          return PIPE2;
        }
        if (pos_ < end_ && *pos_ == '@') {
          ++pos_;
          return PIPEAT;
        }
        return PIPE;
      default: {
        if (isalnum((unsigned char)c) || c == '_' || c == '.' || c == '-') {
          return IDENT;
        }
        return UNKNOWN;
      }
    }
  }
}

Lexer::Token Lexer::PeekToken() {
  const char* save = pos_;
  Token t = ReadToken();
  pos_ = save;
  return t;
}

bool Lexer::PeekToken(Token token) {
  const char* save = pos_;
  Token t = ReadToken();
  pos_ = save;
  return t == token;
}

bool Lexer::ReadIdent(string* out) {
  const char* start = pos_;
  while (pos_ < end_) {
    char c = *pos_;
    if (isalnum((unsigned char)c) || c == '_' || c == '.' || c == '-')
      ++pos_;
    else
      break;
  }
  if (pos_ == start)
    return false;
  out->assign(start, pos_ - start);
  return true;
}

// Reads a $-escaped string.  When |path| is true the read terminates at a
// space, ':' or newline; otherwise it terminates at a newline (and at '='
// for the beginning of a binding).
bool Lexer::ReadValueImpl(string* out, bool path, string* err) {
  out->clear();
  // Leading whitespace is stripped for values, not for paths.
  if (!path) {
    while (pos_ < end_ && (*pos_ == ' ' || *pos_ == '\t' || *pos_ == '\r'))
      ++pos_;
  }
  for (;;) {
    if (pos_ >= end_)
      return true;
    char c = *pos_;
    if (c == '\n')
      return true;
    if (path && (c == ' ' || c == ':' || c == '\t'))
      return true;
    if (!path && (c == '=' || c == ' ' || c == ':' || c == '\t'))
      return true;
    if (c == '$') {
      ++pos_;
      if (pos_ >= end_) {
        Error("bad $-escape (literal $ must be written as $$)", err);
        return false;
      }
      char e = *pos_;
      if (e == '\n') {
        ++pos_;
