        while (pos_ < end_ && (*pos_ == ' ' || *pos_ == '\t' || *pos_ == '\r'))
          ++pos_;
        continue;
      } else if (e == ' ' || e == '\t') {
        out->push_back(' ');
        ++pos_;
        continue;
      } else if (e == ':') {
        out->push_back(':');
        ++pos_;
        continue;
      } else if (e == '$') {
