                      message.c_str());
  return false;
}

const char* Lexer::TokenName(Token token) const {
  switch (token) {
    case NEWLINE: return "newline";
    case INDENT: return "indent";
    case IDENT: return "identifier";
    case COLON: return "':'";
    case PIPE: return "'|'";
    case PIPE2: return "'||'";
    case PIPEAT: return "'|@'";
    case EQUALS: return "'='";
    case EOF_TOKEN: return "eof";
    default: return "lexing error";
  }
}

Lexer::Token Lexer::ReadToken() {
  for (;;) {
    if (pos_ >= end_)
      return EOF_TOKEN;
    // At the beginning of a line, leading whitespace introduces an
    // indentation token.
    if (AtLineStart() && *pos_ == ' ') {
      const char* p = pos_;
      while (p < end_ && (*p == ' ' || *p == '\t'))
        ++p;
      if (p < end_ && *p == '\n') {
        // A blank line: not an indent.
        pos_ = p;
        continue;
      }
      if (p < end_ && *p == '#') {
        // A comment line: skip it entirely, including the newline.
        while (p < end_ && *p != '\n')
          ++p;
        if (p < end_)
          ++p;
        pos_ = p;
        continue;
      }
      pos_ = p;
      return INDENT;
    }
    char c = *pos_;
    switch (c) {
      case ' ':
      case '\t':
      case '\r':
        ++pos_;
        continue;
      case '\n':
        ++pos_;
        return NEWLINE;
      case '#':
        // Comments are only recognized at the start of a line.
        if (AtLineStart()) {
          while (pos_ < end_ && *pos_ != '\n')
            ++pos_;
          if (pos_ < end_)
            ++pos_;
          continue;
        }
        return UNKNOWN;
      case '=':
        ++pos_;
        return EQUALS;
      case ':':
        ++pos_;
        return COLON;
      case '|':
        ++pos_;
        if (pos_ < end_ && *pos_ == '|') {
          ++pos_;
          return PIPE2;
        }
        if (pos_ < end_ && *pos_ == '@') {
          ++pos_;
          return PIPEAT;
        }
        return PIPE;
      default: {
        if (isalnum((unsigned char)c) || c == '_' || c == '.' || c == '-') {
