#include "ninja.h"

#include <string.h>

bool EvalString::Parse(const string& input, string* err) {
  parsed_.clear();
  parsed_ = true;
  const char* p = input.data();
  const char* end = p + input.size();
  while (p < end) {
    if (*p == '$') {
      ++p;
      if (p >= end) {
        *err = "bad $-escape (literal $ must be written as $$)";
        return false;
      }
      char e = *p;
      if (e == '\n') {
        // Should not happen: newlines are already handled by the lexer.
        ++p;
        continue;
      } else if (e == ' ' || e == '\t') {
        parsed_.push_back(TokenItem(" ", RAW));
        ++p;
        continue;
      } else if (e == ':') {
        parsed_.push_back(TokenItem(":", RAW));
        ++p;
        continue;
      } else if (e == '$') {
        parsed_.push_back(TokenItem("$", RAW));
        ++p;
        continue;
      } else if (e == '^') {
        parsed_.push_back(TokenItem("\n", RAW));
        ++p;
        continue;
      } else if (e == '{') {
        ++p;
        const char* start = p;
        while (p < end && *p != '}')
          ++p;
        if (p >= end) {
          *err = "bad $-escape (literal $ must be written as $$)";
          return false;
        }
        string var(start, p - start);
        ++p;
        Token tok = (var == "in" || var == "out" || var == "in_newline")
                        ? SPECIAL : ESCAPED;
        parsed_.push_back(TokenItem(var, tok));
        continue;
      } else {
        const char* start = p;
        while (p < end) {
          char c = *p;
          if (strchr(" \t\r\n=:$", c) || c == '{' || c == '}')
            break;
          ++p;
        }
        if (p == start) {
          *err = "bad $-escape (literal $ must be written as $$)";
          return false;
        }
        string var(start, p - start);
        Token tok = (var == "in" || var == "out" || var == "in_newline")
                        ? SPECIAL : ESCAPED;
        parsed_.push_back(TokenItem(var, tok));
        continue;
      }
    }
    const char* start = p;
    while (p < end && *p != '$')
      ++p;
    parsed_.push_back(TokenItem(string(start, p - start), RAW));
  }
  return true;
}

bool EvalString::Evaluate(Env* env, string* out, string* err) const {
  for (size_t i = 0; i < parsed_.size(); ++i) {
    if (parsed_[i].token == RAW) {
      out->append(parsed_[i].text);
      continue;
    }
    const string* value = env->LookupVariable(parsed_[i].text);
    if (!value)
      continue;
    if (parsed_[i].token != SPECIAL) {
      out->append(*value);
      continue;
    }
    // $in, $out and $in_newline are lists of paths: escape each one.
    const char* list_sep = (parsed_[i].text == "in_newline") ? "\n" : " ";
    const string& val = *value;
    size_t pos = 0;
    while (pos <= val.size()) {
      size_t next = val.find(list_sep, pos);
      if (next == string::npos) {
        out->append(ShellEscape(val.substr(pos)));
        break;
      }
      out->append(ShellEscape(val.substr(pos, next - pos)));
      out->append(list_sep);
      pos = next + 1;
    }
  }
  return true;
}

bool EvalString::EvaluateRaw(Env* env, string* out, string* err) const {
  for (size_t i = 0; i < parsed_.size(); ++i) {
    if (parsed_[i].token == RAW) {
      out->append(parsed_[i].text);
      continue;
    }
    const string* value = env->LookupVariable(parsed_[i].text);
    if (value)
      out->append(*value);
  }
  return true;
}

string EvalString::Serialize() const {
  string out;
  for (size_t i = 0; i < parsed_.size(); ++i) {
    if (parsed_[i].token == RAW) {
      out.append(parsed_[i].text);
    } else {
      out.append("${");
      out.append(parsed_[i].text);
      out.append("}");
    }
  }
  return out;
}
