#include "build_log.h"

#include <errno.h>
#include <stdio.h>
#include <string.h>

const char* BuildLog::kFileSignature = "# ninja log v7\n";

bool BuildLog::Load(const string& path, string* err) {
  string contents;
  string read_err;
  if (!ReadFile(path, &contents, &read_err)) {
    if (read_err.find("No such file") != string::npos)
      return true;  // No log yet.
    *err = read_err;
    return false;
  }
  n_records_ = n_commands_ = 0;
  last_command_id_ = 0;
  size_t offset = 0;
  size_t line_start = 0;
  bool first = true;
  for (size_t i = 0; i <= contents.size(); ++i) {
    if (i < contents.size() && contents[i] != '\n')
      continue;
    string line = contents.substr(line_start, i - line_start);
    line_start = i + 1;
    if (first) {
      first = false;
      if (line != kFileSignature) {
        if (line.empty()) break;
        *err = "bad log version";
        return false;
      }
      continue;
    }
    if (line.empty())
      continue;
    ++n_records_;
    // Parse: start\tend\tmtime\tpath\thash
    vector<string> fields = Split(line, '\t');
    if (fields.size() != 5) {
      *err = "bad log line";
      return false;
    }
    int start = atoi(fields[0].c_str());
    int end = atoi(fields[1].c_str());
    int64_t mtime = strtoll(fields[2].c_str(), NULL, 10);
    uint64_t hash = strtoull(fields[4].c_str(), NULL, 16);
    n_commands_ += end - start;
    last_command_id_ = start;
    // The last entry for a path wins.
    entries_[fields[3]] = BuildLogEntry(mtime, hash);
  }
  return true;
}

bool BuildLog::OpenForWrite(const string& path, string* err) {
  log_file_ = fopen(path.c_str(), "ab");
  if (!log_file_) {
    *err = strerror(errno);
    return false;
  }
  // If the file was empty (or we just created it), write the signature.
  if (ftell(log_file_) == 0)
    fputs(kFileSignature, log_file_);
  return true;
}

void BuildLog::Close() {
  if (log_file_) {
    fclose(log_file_);
    log_file_ = NULL;
  }
}

void BuildLog::RecordCommand(Edge* edge, int start_time, int end_time,
                             int64_t restat_mtime, uint64_t hash) {
