cat > deps_log.cc <<'EOF'
#include "deps_log.h"

#include <errno.h>
#include <stdio.h>
#include <string.h>

const char* DepsLog::kFileSignature = "# ninjadeps\n";
static const unsigned int kDepsLogVersion = 4;

bool DepsLog::Load(const string& path, string* err) {
  string contents;
  string read_err;
  if (!ReadFile(path, &contents, &read_err)) {
    if (read_err.find("No such file") != string::npos)
      return true;
    *err = read_err;
    return false;
  }
  if (contents.size() < 16 ||
      memcmp(contents.data(), kFileSignature, 12) != 0) {
    *err = "bad deps log signature";
    return false;
  }
  unsigned int version;
  memcpy(&version, contents.data() + 12, 4);
  if (version != kDepsLogVersion) {
    *err = StringPrintf("deps log version %d is not supported", version);
    return false;
  }
  const char* p = contents.data() + 16;
  const char* end = contents.data() + contents.size();
  int next_node_id = 0;
  while (p + 4 <= end) {
    unsigned int size;
    memcpy(&size, p, 4);
    p += 4;
    if (size & 0x80000000u) {
      // Deps record: node id, mtime, deps
      unsigned int payload = size & 0x7fffffffu;
      if (payload < 12 || p + payload > end) {
        *err = "bad deps log record";
        return false;
      }
      unsigned int node_id;
      memcpy(&node_id, p, 4);
      int64_t mtime;
      memcpy(&mtime, p + 4, 8);
      int count = (payload - 12) / 4;
      DepsLogDeps* deps = new DepsLogDeps;
      deps->node_count = count;
      deps->mtime = mtime;
      deps->nodes = new int[count];
      for (int i = 0; i < count; ++i) {
        unsigned int d;
        memcpy(&d, p + 12 + 4 * i, 4);
        deps->nodes[i] = (int)d;
      }
      if ((int)node_id < (int)path_by_index_.size()) {
        Node* node = state_node(path_by_index_[node_id]);
        if (node)
          deps_[node] = deps;
      }
      p += payload;
      ++total_deps_records_;
      deps_record_size_ += 4 + payload;
      continue;
    }
    // Path record: path padded, then ~node id.
    if (p + size > end) {
      *err = "bad deps log record";
      return false;
    }
    string path(p, size - 4);
    path.resize(path.find('\0') == string::npos ? path.size()
                                                : path.find('\0'));
    p += size;
    unsigned int id;
    memcpy(&id, p, 4);
    p += 4;
    int node_id = (int)(~id);
    if (path_by_index_.size() <= (size_t)node_id)
      path_by_index_.resize(node_id + 1);
    path_by_index_[node_id] = path;
    path_index_[path] = node_id;
    ++next_node_id;
    ++total_paths_;
  }
  return true;
}
