cat > deps_log.cc <<'EOF'
#include "deps_log.h"

#include <errno.h>
#include <stdio.h>
#include <string.h>

const char* DepsLog::kFileSignature = "# ninjadeps\n";
static const unsigned int kDepsLogVersion = 4;

int DepsLog::PathIndex(const string& path) const {
  map<string, int>::const_iterator i = path_index_.find(path);
  if (i == path_index_.end())
    return -1;
  return i->second;
}

bool DepsLog::Load(const string& path, State* state, string* err) {
  string contents;
  string read_err;
  if (!ReadFile(path, &contents, &read_err)) {
    if (read_err.find("No such file") != string::npos)
      return true;
    *err = read_err;
    return false;
  }
  if (contents.size() < 16 ||
      memcmp(contents.data(), kFileSignature, 12) != 0) {
    *err = "bad deps log signature";
    return false;
  }
  unsigned int version;
  memcpy(&version, contents.data() + 12, 4);
  if (version != kDepsLogVersion) {
    *err = StringPrintf("deps log version %d is not supported", version);
    return false;
  }
  const char* p = contents.data() + 16;
  const char* end = contents.data() + contents.size();
  vector<string> path_by_index;
  while (p + 4 <= end) {
    unsigned int size;
    memcpy(&size, p, 4);
    p += 4;
    if (size & 0x80000000u) {
      unsigned int payload = size & 0x7fffffffu;
      if (payload < 12 || (int64_t)(end - p) < (int64_t)payload) {
        *err = "bad deps log record";
        return false;
      }
      unsigned int node_id;
      memcpy(&node_id, p, 4);
      int64_t mtime;
      memcpy(&mtime, p + 4, 8);
      int count = (payload - 12) / 4;
      if ((int)node_id < (int)path_by_index.size()) {
        const string& node_path = path_by_index[node_id];
        Node* node = state->GetNode(node_path);
        if (node) {
          DepsLogDeps* deps = new DepsLogDeps;
          deps->node_count = count;
          deps->mtime = mtime;
          deps->nodes = new int[count];
          for (int i = 0; i < count; ++i) {
            unsigned int d;
            memcpy(&d, p + 12 + 4 * i, 4);
            deps->nodes[i] = (int)d;
          }
          deps_by_path_[node_path] = deps;
        }
      }
      p += payload;
      ++deps_record_count_;
      continue;
    }
    if ((int64_t)(end - p) < (int64_t)size) {
      *err = "bad deps log record";
      return false;
    }
    string node_path(p, size);
    size_t nul = node_path.find('\0');
    if (nul != string::npos)
      node_path.resize(nul);
    p += size;
    unsigned int id;
    memcpy(&id, p, 4);
    p += 4;
    int node_id = (int)(~id);
    if (path_by_index.size() <= (size_t)node_id)
      path_by_index.resize(node_id + 1);
    path_by_index[node_id] = node_path;
    path_index_[node_path] = node_id;
    if (next_node_id_ <= node_id)
      next_node_id_ = node_id + 1;
  }
  return true;
}

bool DepsLog::OpenForWrite(const string& path, string* err) {
  deps_file_ = fopen(path.c_str(), "ab");
  if (!deps_file_) {
    *err = strerror(errno);
    return false;
  }
  if (ftell(deps_file_) == 0) {
    fputs(kFileSignature, deps_file_);
    unsigned int version = kDepsLogVersion;
    fwrite(&version, 4, 1, deps_file_);
    next_node_id_ = 0;
  }
  return true;
}

void DepsLog::Close() {
  if (deps_file_) {
    fclose(deps_file_);
    deps_file_ = NULL;
  }
}

bool DepsLog::WritePath(State* state, const string& path, int* node_id,
                        string* err) {
  int id = PathIndex(path);
  if (id < 0) {
    id = next_node_id_++;
    path_index_[path] = id;
    size_t padded = (path.size() + 3) & ~3;
    unsigned int size = 4 + (unsigned int)padded;
    if (fwrite(&size, 4, 1, deps_file_) != 1) {
      *err = "write error";
      return false;
    }
    string padded_path = path;
    padded_path.resize(padded, '\0');
    if (fwrite(padded_path.data(), padded, 1, deps_file_) != 1) {
      *err = "write error";
      return false;
    }
    unsigned int neg = (unsigned int)(~id);
    if (fwrite(&neg, 4, 1, deps_file_) != 1) {
      *err = "write error";
      return false;
    }
  }
  *node_id = id;
  return true;
}

bool DepsLog::RecordDeps(Node* node, int64_t mtime, const vector<Node*>& deps,
                         State* state, string* err) {
  if (!deps_file_)
    return false;
  // Write path records for all nodes involved.
  int node_id;
  if (!WritePath(state, node->path(), &node_id, err))
    return false;
  vector<int> dep_ids;
  for (size_t i = 0; i < deps.size(); ++i) {
    int id;
    if (!WritePath(state, deps[i]->path(), &id, err))
      return false;
    dep_ids.push_back(id);
  }
  unsigned int size = 4 + 8 + 4 * (unsigned int)dep_ids.size();
  unsigned int record = size | 0x80000000u;
  if (fwrite(&record, 4, 1, deps_file_) != 1) {
    *err = "write error";
    return false;
  }
  if (fwrite(&node_id, 4, 1, deps_file_) != 1) {
    *err = "write error";
    return false;
  }
  if (fwrite(&mtime, 8, 1, deps_file_) != 1) {
    *err = "write error";
    return false;
  }
  for (size_t i = 0; i < dep_ids.size(); ++i) {
    if (fwrite(&dep_ids[i], 4, 1, deps_file_) != 1) {
      *err = "write error";
      return false;
    }
  }
  ++deps_record_count_;
  // Record in memory too.
  map<string, DepsLogDeps*>::iterator i = deps_by_path_.find(node->path());
  if (i != deps_by_path_.end())
    delete i->second;
  DepsLogDeps* d = new DepsLogDeps;
  d->node_count = (int)dep_ids.size();
  d->mtime = mtime;
  d->nodes = new int[dep_ids.size()];
  for (size_t j = 0; j < dep_ids.size(); ++j)
    d->nodes[j] = dep_ids[j];
  deps_by_path_[node->path()] = d;
  return true;
}

const DepsLogDeps* DepsLog::GetDeps(Node* node) const {
  map<string, DepsLogDeps*>::const_iterator i = deps_by_path_.find(node->path());
  if (i == deps_by_path_.end())
    return NULL;
  return i->second;
}
