cat > manifest.cc <<'EOF'
#include "manifest.h"
#include "disk.h"
#include "build_log.h"
#include "deps_log.h"

#include <stdio.h>
#include <string.h>

// ---------------------------------------------------------------------------
// State

State::State() {
  Rule* phony = new Rule("phony");
  rule_map_["phony"] = phony;
  rules_.push_back(phony);
}

Rule* State::LookupRule(const string& name) {
  map<string, Rule*>::iterator i = rule_map_.find(name);
  if (i == rule_map_.end())
    return NULL;
  return i->second;
}

Pool* State::LookupPool(const string& name) {
  map<string, Pool*>::iterator i = pool_map_.find(name);
  if (i == pool_map_.end())
    return NULL;
  return i->second;
}

Node* State::GetNode(const string& path) {
  unordered_map<string, Node*>::iterator i = node_map_.find(path);
  if (i != node_map_.end())
    return i->second;
  Node* node = new Node;
  node->set_path(path);
  node_map_[path] = node;
  nodes_.push_back(node);
  return node;
}

Node* State::LookupNode(const string& path) const {
  unordered_map<string, Node*>::const_iterator i = node_map_.find(path);
  if (i == node_map_.end())
    return NULL;
  return i->second;
}

bool State::AddRule(Rule* rule, string* err) {
  if (rule_map_.count(rule->name())) {
    *err = "duplicate rule '" + rule->name() + "'";
    return false;
  }
  rule_map_[rule->name()] = rule;
  rules_.push_back(rule);
  return true;
}

bool State::AddPool(Pool* pool, string* err) {
  if (pool_map_.count(pool->name())) {
    *err = "duplicate pool '" + pool->name() + "'";
    return false;
  }
  pool_map_[pool->name()] = pool;
  pools_.push_back(pool);
  return true;
}

bool State::AddEdge(Edge* edge, string* err) {
  for (size_t i = 0; i < edge->outputs_.size(); ++i) {
    Node* output = edge->outputs_[i];
    if (output->in_edge()) {
      *err = "multiple rules generate " + output->path();
      return false;
    }
    output->set_in_edge(edge);
  }
  for (size_t i = 0; i < edge->outputs_.size(); ++i) {
    Node* output = edge->outputs_[i];
    for (size_t j = 0; j < edge->inputs_.size(); ++j) {
      Node* input = edge->inputs_[j];
      if (input == output)
        continue;
      input->AddOutEdge(edge);
    }
    for (size_t j = 0; j < edge->order_only_deps_.size(); ++j) {
      Node* input = edge->order_only_deps_[j];
      if (input == output)
        continue;
      input->AddOutEdge(edge);
    }
    for (size_t j = 0; j < edge->validations_.size(); ++j) {
      Node* input = edge->validations_[j];
      if (input == output)
        continue;
      input->AddOutEdge(edge);
    }
  }
  edges_.push_back(edge);
  return true;
}
EOF
echo ok"}

