// ---------------------------------------------------------------------------
// ManifestParser

bool ManifestParser::ExpectToken(Lexer::Token token, const char* expected,
                                 string* err) {
  Lexer::Token t = lexer_.ReadToken();
  if (t == token)
    return true;
  if (t == Lexer::EOF_TOKEN) {
    lexer_.Error("unexpected EOF", err);
    return false;
  }
  lexer_.Error(StringPrintf("expected %s, got %s", expected,
                            lexer_.TokenName(t)), err);
  return false;
}

bool ManifestParser::ParseLet(string* key, string* val, string* err) {
  if (!lexer_.ReadIdent(key)) {
    lexer_.Error("expected variable name", err);
    return false;
  }
  if (!ExpectToken(Lexer::EQUALS, "'='", err))
    return false;
  if (!lexer_.ReadValue(val, err))
    return false;
  return true;
}

// Reads a list of paths, terminated by a newline (or, for outputs, by a
// colon).  Separators '|' (implicit), '||' (order-only) and '|@'
// (validations) split the list.
struct PathList {
  vector<string> explicit_;
  vector<string> implicit;
  vector<string> order_only;
  vector<string> validations;
};

bool ParsePathList(Lexer* lexer, PathList* list, bool stop_at_colon,
                   string* err) {
  int section = 0;  // 0 = explicit, 1 = implicit, 2 = order-only, 3 = valid.
  for (;;) {
    // Skip whitespace (but not comments).
    while (!lexer->AtLineStart()) {
      char c = *lexer->GetPos();
      if (c == ' ')
        lexer->SetPos(lexer->GetPos() + 1);
      else
        break;
    }
    if (lexer->GetPos() >= lexer->GetPos()) {}
    const char* p = lexer->GetPos();
    if (*p == '\0') {
      lexer->Error("unexpected EOF", err);
      return false;
    }
    if (*p == '\n') {
      if (stop_at_colon) {
        lexer->Error("expected ':', got newline ($ also escapes ':')", err);
        return false;
      }
      return true;
    }
    if (stop_at_colon && *p == ':') {
      lexer->SetPos(p + 1);
      return true;
    }
    if (*p == '|') {
      const char* q = p + 1;
      if (*q == '|') {
        lexer->SetPos(q + 1);
        section = 2;
        continue;
      }
      if (*q == '@') {
        lexer->SetPos(q + 1);
        section = 3;
        continue;
      }
      lexer->SetPos(q);
      section = 1;
      continue;
    }
    if (*p == ':' && !stop_at_colon) {
      lexer->Error(StringPrintf("expected newline, got %s",
                                lexer->TokenName(Lexer::COLON)), err);
      return false;
    }
    string path;
    if (!lexer->ReadPath(&path, err))
      return false;
    if (path.empty()) {
      lexer->Error("expected path", err);
      return false;
    }
    CanonicalizePath(&path);
    vector<string>* out = &list->explicit_;
    if (section == 1) out = &list->implicit;
    else if (section == 2) out = &list->order_only;
    else if (section == 3) out = &list->validations;
    out->push_back(path);
  }
}

bool ManifestParser::ParseRule(string* err) {
  string rule_name;
  if (!lexer_.ReadIdent(&rule_name)) {
    lexer_.Error("expected rule name", err);
    return false;
  }
  if (!ExpectToken(Lexer::NEWLINE, "newline", err))
    return false;
  Rule* rule = new Rule(rule_name);
  // The command must be present.
  bool has_command = false;
  bool has_rspfile = false, has_rspfile_content = false;
  while (lexer_.PeekToken(Lexer::INDENT)) {
    lexer_.ReadToken();  // consume the indent
    string key, val;
    if (!ParseLet(&key, &val, err))
      return false;
    static const char* kValidRuleVars[] = {
      "command", "depfile", "deps", "msvc_deps_prefix", "description",
      "dyndep", "generator", "restat", "rspfile", "rspfile_content", "pool",
      NULL
    };
    bool valid = false;
    for (int i = 0; kValidRuleVars[i]; ++i)
      if (key == kValidRuleVars[i])
        valid = true;
    if (!valid) {
      lexer_.Error("unexpected variable '" + key + "'", err);
      return false;
    }
    EvalString eval;
    if (!eval.Parse(val, err))
      return false;
    rule->bindings_[key] = eval;
    if (key == "command") has_command = true;
    if (key == "rspfile") has_rspfile = true;
    if (key == "rspfile_content") has_rspfile_content = true;
  }
  if (!has_command) {
    lexer_.ErrorNoContext("expected 'command =' line", err);
    return false;
  }
  if (has_rspfile != has_rspfile_content) {
    lexer_.ErrorNoContext(
        "rspfile and rspfile_content need to be both specified", err);
    return false;
  }
  if (!state_->AddRule(rule, err)) {
    lexer_.ErrorNoContext(*err, err);
    return false;
  }
  file_rules_->Add(rule);
  return true;
}

bool ManifestParser::ParsePool(string* err) {
  string pool_name;
  if (!lexer_.ReadIdent(&pool_name)) {
    lexer_.Error("expected pool name", err);
    return false;
  }
  if (!ExpectToken(Lexer::NEWLINE, "newline", err))
    return false;
  Pool* pool = new Pool(pool_name);
  bool has_depth = false;
  while (lexer_.PeekToken(Lexer::INDENT)) {
    lexer_.ReadToken();
    string key, val;
    if (!ParseLet(&key, &val, err))
      return false;
    if (key != "depth") {
      lexer_.Error("unexpected variable '" + key + "'", err);
      return false;
    }
    EvalString eval;
    if (!eval.Parse(val, err))
      return false;
    string expanded;
    Env empty_env;
    if (!eval.EvaluateRaw(&empty_env, &expanded, err))
      return false;
    pool->depth_ = atoi(expanded.c_str());
    has_depth = true;
  }
  if (!has_depth) {
    lexer_.ErrorNoContext("expected 'depth =' line", err);
    return false;
  }
  if (!state_->AddPool(pool, err)) {
    lexer_.ErrorNoContext(*err, err);
    return false;
  }
  return true;
}

bool ManifestParser::ParseDefault(string* err) {
  PathList list;
  if (!ParsePathList(&lexer_, &list, false, err))
    return false;
  if (!ExpectToken(Lexer::NEWLINE, "newline", err))
    return false;
  if (list.explicit_.empty()) {
    lexer_.Error("expected target name", err);
    return false;
  }
  for (size_t i = 0; i < list.explicit_.size(); ++i) {
    Node* node = state_->GetNode(list.explicit_[i]);
    if (!node) {
      *err = "unknown target '" + list.explicit_[i] + "'";
      lexer_.Error(*err, err);
      return false;
    }
    state_->default_targets_.push_back(node);
  }
  return true;
}

bool ManifestParser::ParseEdge(string* err) {
  Edge* edge = new Edge();
  edge->env_ = new Scope(file_env_);
  edge->id_ = (int)state_->edges_.size();
  PathList outs;
  if (!ParsePathList(&lexer_, &outs, true, err))
    return false;
  for (size_t i = 0; i < outs.explicit_.size(); ++i)
    edge->outputs_.push_back(state_->GetNode(outs.explicit_[i]));
  for (size_t i = 0; i < outs.implicit.size(); ++i)
    edge->implicit_outs_.push_back(state_->GetNode(outs.implicit[i]));

  const char* rule_pos = lexer_.GetPos();
  string rule_name;
  if (!lexer_.ReadIdent(&rule_name)) {
    lexer_.Error("expected build command name", err);
    return false;
  }
  Rule* rule = file_rules_->Lookup(rule_name);
  if (!rule) {
    const char* save = lexer_.GetPos();
    lexer_.SetPos(rule_pos);
    lexer_.Error("unknown build rule '" + rule_name + "'", err);
    lexer_.SetPos(save);
    return false;
  }
  edge->rule_ = rule;
  edge->is_phony_ = (rule->name() == "phony");

  PathList ins;
  if (!ParsePathList(&lexer_, &ins, false, err))
    return false;
  if (!ExpectToken(Lexer::NEWLINE, "newline", err))
    return false;
  for (size_t i = 0; i < ins.explicit_.size(); ++i)
    edge->inputs_.push_back(state_->GetNode(ins.explicit_[i]));
  for (size_t i = 0; i < ins.implicit.size(); ++i)
    edge->inputs_.push_back(state_->GetNode(ins.implicit[i]));
  for (size_t i = 0; i < ins.order_only.size(); ++i)
    edge->order_only_deps_.push_back(state_->GetNode(ins.order_only[i]));
  for (size_t i = 0; i < ins.validations.size(); ++i)
    edge->validations_.push_back(state_->GetNode(ins.validations[i]));

  // Parse the edge-level bindings.
  while (lexer_.PeekToken(Lexer::INDENT)) {
    lexer_.ReadToken();
    string key, val;
    if (!ParseLet(&key, &val, err))
      return false;
    EvalString eval;
    if (!eval.Parse(val, err))
      return false;
    string expanded;
    Env* env = edge->env_;
    if (!eval.EvaluateRaw(env, &expanded, err))
      return false;
    ((Scope*)edge->env_)->AddBinding(key, expanded);
  }

  // Resolve the pool.
  const string* pool_name = ((Scope*)edge->env_)->LookupVariable("pool");
  if (pool_name) {
    if (pool_name->empty()) {
      edge->pool_ = NULL;
    } else {
      Pool* pool = state_->LookupPool(*pool_name);
      if (!pool) {
        lexer_.ErrorNoContext("unknown pool name '" + *pool_name + "'", err);
        return false;
      }
      edge->pool_ = pool;
    }
  }

  // Resolve dyndep.
  const string* dyndep_name = ((Scope*)edge->env_)->LookupVariable("dyndep");
  if (dyndep_name && !dyndep_name->empty()) {
    bool found = false;
    for (size_t i = 0; i < edge->inputs_.size(); ++i)
      if (edge->inputs_[i]->path() == *dyndep_name) {
        edge->dyndep_ = edge->inputs_[i];
        found = true;
      }
    if (!found) {
      lexer_.ErrorNoContext("dyndep '" + *dyndep_name + "' is not an input",
                            err);
      return false;
    }
  }

  // The deps type.
  const string* deps = ((Scope*)edge->env_)->LookupVariable("deps");
  if (deps && !deps->empty()) {
    if (*deps == "gcc") edge->deps_type_ = Edge::kGCC;
    else if (*deps == "msvc") edge->deps_type_ = Edge::kMSVC;
  }
  const string* restat = ((Scope*)edge->env_)->LookupVariable("restat");
  if (restat && !restat->empty())
    edge->restat_ = true;
  const string* generator = ((Scope*)edge->env_)->LookupVariable("generator");
  if (generator && !generator->empty())
    edge->is_generator_ = true;

  if (!state_->AddEdge(edge, err)) {
    lexer_.ErrorNoContext(*err, err);
    return false;
  }
  return true;
}

bool ManifestParser::ParseFileInclude(bool new_scope, string* err) {
  string path;
  if (!lexer_.ReadPath(&path, err))
    return false;
  if (!ExpectToken(Lexer::NEWLINE, "newline", err))
    return false;
  string contents;
  string read_err;
  if (!disk_->ReadFile(path, &contents, &read_err)) {
    lexer_.Error("loading '" + path + "': " + read_err, err);
    return false;
  }
  CanonicalizePath(&path);
  ManifestParser subparser(state_, disk_);
  subparser.lexer_.Start(path, contents);
  if (new_scope) {
    Scope* child = new Scope(file_env_);
    RuleScope* child_rules = new RuleScope;
    child_rules->parent_ = file_rules_;
    subparser.file_env_ = child;
    subparser.file_rules_ = child_rules;
    if (!subparser.Parse(path, contents, err, true))
      return false;
  } else {
    subparser.file_env_ = file_env_;
    subparser.file_rules_ = file_rules_;
    if (!subparser.Parse(path, contents, err, true))
      return false;
  }
  return true;
}

bool ManifestParser::Parse(const string& filename, const string& input,
                           string* err, bool inner) {
  for (;;) {
    Lexer::Token token = lexer_.ReadToken();
    switch (token) {
      case Lexer::EOF_TOKEN:
        return true;
      case Lexer::NEWLINE:
        continue;
      case Lexer::INDENT:
        lexer_.ErrorNoContext("unexpected indent", err);
        return false;
      case Lexer::IDENT: {
        const char* start = lexer_.GetPos();
        string ident;
        if (!lexer_.ReadIdent(&ident)) {
