#include "graph.h"
#include "deps_parse.h"
#include "disk.h"

#include <stdio.h>
#include <string.h>

uint64_t HashString(const string& s) {
  uint64_t h = 0xcbf29ce484222325ULL;
  for (size_t i = 0; i < s.size(); ++i) {
    h ^= (unsigned char)s[i];
    h *= 0x100000001b3ULL;
  }
  return h;
}

bool DirtyRecomputer::StatNode(Node* node, string* err) {
  if (node->has_stat_)
    return true;
  node->has_stat_ = true;
  int64_t mtime = disk_->Stat(node->path(), err);
  if (mtime < 0)
    return false;
  node->set_mtime(mtime);
  return true;
}

// Loads the dependencies for an edge from the depfile or the deps log.
static bool LoadEdgeDeps(Edge* edge, DirtyRecomputer* rc, State* state,
                         DiskInterface* disk, vector<Node*>* deps,
                         string* err) {
  deps->clear();
  if (edge->deps_type_ != Edge::kNoDeps) {
    DepsLog* deps_log = disk->deps_log();
    if (!deps_log)
      return true;
    const DepsLogDeps* log_deps = deps_log->GetDeps(edge->outputs_[0]);
    if (!log_deps)
      return true;
