#ifndef NINJA_SUBPROCESS_H_
#define NINJA_SUBPROCESS_H_
#include "ninja.h"

struct Subprocess {
  enum ExitStatus { ExitSuccess, ExitFailure, ExitInterrupted };

  Subprocess(bool use_console) : pid_(-1), fd_(-1), use_console_(use_console),
                                 interrupted_(false), exit_code_(0) {}
