  bool use_console() const { return use_console_; }

  pid_t pid_;
  int fd_;
  bool use_console_;
  string output_;
  bool interrupted_;
  int exit_code_;
};

struct SubprocSet {
  ~SubprocSet() { Clear(); }
  void Add(Subprocess* subproc) { running_.push_back(subproc); }
  void Clear();
  /// Wait for at least one subprocess to finish.  Returns the finished one, or
  /// NULL if none finished.
  Subprocess* NextFinished();
  bool more_pending() const { return !running_.empty(); }
