#include "subprocess.h"
#include "disk.h"

#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/select.h>
#include <sys/wait.h>
#include <unistd.h>

Subprocess::~Subprocess() {
  if (pid_ > 0) {
    // Kill the process.
    kill(pid_, SIGTERM);
    int status;
    waitpid(pid_, &status, 0);
  }
  if (fd_ >= 0)
    close(fd_);
}

bool Subprocess::Start(DiskInterface* disk, const string& command, string* err) {
  int output_pipe[2];
  if (!use_console_) {
    if (pipe(output_pipe) < 0) {
      *err = "pipe: " + string(strerror(errno));
      return false;
    }
  }
  pid_ = fork();
  if (pid_ < 0) {
    *err = "fork: " + string(strerror(errno));
    return false;
  }
  if (pid_ == 0) {
    if (!use_console_) {
      close(output_pipe[0]);
      dup2(output_pipe[1], 1);
      dup2(output_pipe[1], 2);
      close(output_pipe[1]);
      // Read from /dev/null for stdin.
      int devnull = open("/dev/null", O_RDONLY);
      if (devnull >= 0) {
        dup2(devnull, 0);
        close(devnull);
      }
    } else {
      // stdin: the console.
    }
    execl("/bin/sh", "/bin/sh", "-c", command.c_str(), (char*)NULL);
    _exit(127);
  }
  if (!use_console_) {
    close(output_pipe[1]);
    fd_ = output_pipe[0];
    // Set the pipe to non-blocking.
    int flags = fcntl(fd_, F_GETFL, 0);
    fcntl(fd_, F_SETFL, flags | O_NONBLOCK);
  } else {
    fd_ = -1;
  }
  return true;
}

void Subprocess::OnPipeReady() {
  char buf[65536];
  for (;;) {
    ssize_t len = read(fd_, buf, sizeof(buf));
    if (len > 0) {
      output_.append(buf, len);
      continue;
    }
    if (len == 0)
      break;
    if (errno == EINTR)
      continue;
    if (errno == EAGAIN || errno == EWOULDBLOCK)
      break;
    // Error: assume the pipe is closed.
    break;
  }
}

Subprocess::ExitStatus Subprocess::Finish() {
  int status = 0;
  while (waitpid(pid_, &status, 0) < 0) {
    if (errno != EINTR) {
      pid_ = 0;
      return ExitFailure;
    }
  }
  pid_ = 0;
  if (WIFSIGNALED(status)) {
    if (WTERMSIG(status) == SIGINT || WTERMSIG(status) == SIGTERM)
      interrupted_ = true;
    return ExitInterrupted;
  }
  if (WIFEXITED(status)) {
    exit_code_ = WEXITSTATUS(status);
    if (exit_code_ == 0)
      return ExitSuccess;
    if (exit_code_ == 130) {
      interrupted_ = true;
      return ExitInterrupted;
    }
    return ExitFailure;
  }
  return ExitFailure;
}

void SubprocSet::Clear() {
  for (size_t i = 0; i < running_.size(); ++i)
    delete running_[i];
  running_.clear();
  for (size_t i = 0; i < finished_.size(); ++i)
    delete finished_[i];
  finished_.clear();
}

void SubprocSet::AddFDs(fd_set* set, int* max_fd) const {
  for (size_t i = 0; i < running_.size(); ++i) {
    int fd = running_[i]->fd();
    if (fd < 0)
      continue;
    FD_SET(fd, set);
    if (fd > *max_fd)
      *max_fd = fd;
  }
}

bool SubprocSet::DoWork() {
  fd_set set;
  FD_ZERO(&set);
  int max_fd = -1;
  AddFDs(&set, &max_fd);
  if (max_fd < 0) {
    if (running_.empty())
      return false;
    // No pipes to wait on: just wait for a child.
    usleep(1000);
    // Check for children that have exited.
    for (size_t i = 0; i < running_.size(); ++i) {
      Subprocess* subproc = running_[i];
      int status;
      if (waitpid(subproc->pid_, &status, WNOHANG) == subproc->pid_) {
        subproc->Finish();
        finished_.push_back(subproc);
        running_.erase(running_.begin() + i);
        --i;
      }
    }
    return true;
  }
  if (select(max_fd + 1, &set, NULL, NULL, NULL) < 0) {
    if (errno == EINTR)
      return true;
    return false;
  }
  for (size_t i = 0; i < running_.size(); ++i) {
    Subprocess* subproc = running_[i];
    if (subproc->fd() < 0)
      continue;
    if (FD_ISSET(subproc->fd(), &set))
      subproc->OnPipeReady();
    // Check whether the process has exited.
    int status;
    if (waitpid(subproc->pid_, &status, WNOHANG) == subproc->pid_) {
      subproc->Finish();
      finished_.push_back(subproc);
      running_.erase(running_.begin() + i);
      --i;
    }
  }
  return true;
}

Subprocess* SubprocSet::NextFinished() {
  if (finished_.empty())
    return NULL;
  Subprocess* subproc = finished_.back();
  finished_.pop_back();
  return subproc;
}
