  string status_progress_format;
  bool explain;
  bool keep_depfile;
  bool keep_rsp;
  int swallow_failures;
};

struct Plan {
  Plan(State* state) : state_(state), wanted_edges_(0), outstanding_(0) {}

  bool AddTarget(Node* target, string* err);
  bool AddEdge(Edge* edge, string* err);
  bool EdgeFinished(Edge* edge, string* err);
  Edge* FindNextEdgeToExecute();
  bool more_to_do() const { return wanted_edges_ > 0; }
  int outstanding() const { return outstanding_; }

