  const BuildConfig& config_;
  DiskInterface* disk_;
  StatusPrinter* status_;
  BuildLog* log_;
  DepsLog* deps_log_;
  Plan plan_;
  DirtyRecomputer recompute_;
  SubprocSet subprocs_;
  int fail_code_;
  int fail_count_;
  bool stopped_early_;
  int64_t start_time_;
};
#endif
