bool Plan::AddTarget(Node* target, string* err) {
  Edge* edge = target->in_edge();
  if (edge && !edge->outputs_ready_ && target->dirty_) {
    if (!AddEdge(edge, err))
      return false;
  }
  if (edge) {
    // Validations are added to the build graph whenever the edge is
    // considered, even if it is not dirty.
    for (size_t i = 0; i < edge->validations_.size(); ++i) {
      Node* validation = edge->validations_[i];
      if (!AddTarget(validation, err))
        return false;
    }
    if (target->dirty_ && edge->outputs_ready_ == false) {
      for (size_t i = 0; i < edge->inputs_.size(); ++i) {
        Node* input = edge->inputs_[i];
        if (!input->dirty_)
          continue;
        if (!AddTarget(input, err))
          return false;
      }
      for (size_t i = 0; i < edge->order_only_deps_.size(); ++i) {
        Node* input = edge->order_only_deps_[i];
        if (!input->dirty_)
          continue;
        if (!AddTarget(input, err))
          return false;
      }
      if (edge->dyndep_ && edge->dyndep_->dirty_) {
        if (!AddTarget(edge->dyndep_, err))
          return false;
      }
    }
  }
  return true;
}

bool Plan::AddEdge(Edge* edge, string* err) {
  if (edge->outputs_ready_)
    return true;
  if (added_.count(edge))
    return true;
  added_.insert(edge);
  ++wanted_edges_;
  int unfinished = 0;
  for (size_t i = 0; i < edge->inputs_.size(); ++i) {
    Node* input = edge->inputs_[i];
    if (!input->dirty_)
      continue;
    Edge* in_edge = input->in_edge();
    if (!in_edge)
      continue;
    if (!AddEdge(in_edge, err))
      return false;
    if (!in_edge->outputs_ready_)
      ++unfinished;
  }
  for (size_t i = 0; i < edge->order_only_deps_.size(); ++i) {
    Node* input = edge->order_only_deps_[i];
    if (!input->dirty_)
      continue;
    Edge* in_edge = input->in_edge();
    if (!in_edge)
      continue;
    if (!AddEdge(in_edge, err))
      return false;
    if (!in_edge->outputs_ready_)
      ++unfinished;
  }
  if (edge->dyndep_ && edge->dyndep_->dirty_) {
    Edge* in_edge = edge->dyndep_->in_edge();
    if (in_edge) {
      if (!AddEdge(in_edge, err))
        return false;
      if (!in_edge->outputs_ready_)
        ++unfinished;
    }
  }
  unfinished_inputs_[edge] = unfinished;
  if (unfinished == 0)
    ready_.insert(edge);
  return true;
}

Edge* Plan::FindNextEdgeToExecute() {
  if (ready_.empty())
    return NULL;
  set<Edge*>::iterator i = ready_.begin();
  Edge* edge = *i;
  ready_.erase(i);
  return edge;
}

bool Plan::EdgeFinished(Edge* edge, string* err) {
  edge->outputs_ready_ = true;
  for (size_t i = 0; i < edge->outputs_.size(); ++i) {
    Node* output = edge->outputs_[i];
    for (size_t j = 0; j < output->out_edges().size(); ++j) {
      Edge* depend = output->out_edges()[j];
      if (depend == edge)
        continue;
      map<Edge*, int>::iterator it = unfinished_inputs_.find(depend);
      if (it == unfinished_inputs_.end())
        continue;
      --it->second;
      if (it->second == 0)
        ready_.insert(depend);
    }
  }
  return true;
}
