Builder::Builder(State* state, const BuildConfig& config, DiskInterface* disk,
                 StatusPrinter* status)
    : state_(state), config_(config), disk_(disk), status_(status),
      log_(NULL), deps_log_(NULL), plan_(state), recompute_(state, disk),
      fail_code_(0), fail_count_(0), stopped_early_(false),
      start_time_(GetTimeMillis()) {}

bool Builder::RecomputeDirty(string* err) {
  recompute_.explain_ = config_.explain;
  // Recompute the dirty state for the default targets and the validations.
  vector<Node*> targets = state_->default_targets_;
  if (!recompute_.RecomputeDirty(targets, err))
    return false;
  // Recompute dirty state for all targets of all edges (so that the plan
  // sees consistent dirty state).
  for (size_t i = 0; i < state_->edges_.size(); ++i) {
    Edge* edge = state_->edges_[i];
    for (size_t j = 0; j < edge->outputs_.size(); ++j)
      if (!recompute_.RecomputeNode(edge->outputs_[j], err))
        return false;
    for (size_t j = 0; j < edge->inputs_.size(); ++j)
      if (!recompute_.RecomputeNode(edge->inputs_[j], err))
        return false;
  }
  return true;
}

bool Builder::ExpandCommand(Edge* edge, string* command, string* err) {
  const EvalString* cmd = edge->GetBinding("command");
  if (!cmd) {
    *err = StringPrintf("edge '%s' has no command", edge->rule_->name().c_str());
    return false;
  }
  if (!cmd->Evaluate(edge->env_, command, err))
    return false;
  const EvalString* rspfile = edge->GetBinding("rspfile");
  const EvalString* rspfile_content = edge->GetBinding("rspfile_content");
  if (rspfile && rspfile_content) {
    string rsp_path;
    if (!rspfile->Evaluate(edge->env_, &rsp_path, err))
      return false;
    string rsp_content;
    if (!rspfile_content->Evaluate(edge->env_, &rsp_content, err))
      return false;
    if (!disk_->MakeDirs(rsp_path)) {
      *err = "cannot create rsp file directory";
      return false;
    }
    FILE* f = fopen(rsp_path.c_str(), "w");
    if (!f) {
      *err = strerror(errno);
      return false;
    }
    fwrite(rsp_content.data(), rsp_content.size(), 1, f);
    fclose(f);
    // Replace "@" followed by the rsp path with the expanded content if
    // requested by the compdb tool; otherwise leave it as is.
  }
  return true;
}

bool Builder::StartEdge(Edge* edge, Subprocess** subproc_out, string* err) {
  string command;
  if (!ExpandCommand(edge, &command, err))
    return false;
  // Make sure the output directories exist.
  if (!config_.dry_run) {
    for (size_t i = 0; i < edge->outputs_.size(); ++i) {
      if (!disk_->MakeDirs(edge->outputs_[i]->path())) {
        *err = StringPrintf("cannot create directory for %s",
                            edge->outputs_[i]->path().c_str());
        return false;
      }
    }
  }
  bool use_console = (edge->pool_ && edge->pool_->name() == "console");
  Subprocess* subproc = new Subprocess(use_console);
  if (config_.dry_run) {
    delete subproc;
    *subproc_out = NULL;
    status_->BuildEdgeStarted(edge);
    status_->BuildFinished(edge, 0, string(), true);
    edge->outputs_ready_ = true;
    return true;
  }
  if (!subproc->Start(disk_, command, err)) {
    delete subproc;
    return false;
  }
  *subproc_out = subproc;
  running_[subproc] = edge;
  subprocs_.Add(subproc);
  ++plan_.outstanding_;
  status_->BuildEdgeStarted(edge);
  return true;
}
