bool Builder::FinishCommand(Edge* edge, Subprocess* subproc, string* err) {
  --plan_.outstanding_;
  running_.erase(subproc);
  Subprocess::ExitStatus status = subproc->Finish();
  int exit_code = subproc->exit_code();
  bool success = (status == Subprocess::ExitSuccess);
  const string output = subproc->GetOutput();
  delete subproc;

  if (!success && status == Subprocess::ExitInterrupted) {
    // The user hit ^C.
    return false;
  }

  // Print the failed line.
  if (!success) {
    string outputs;
    for (size_t i = 0; i < edge->outputs_.size(); ++i)
      outputs += edge->outputs_[i]->path() + " ";
    printf("FAILED: [code=%d] %s\n", exit_code, outputs.c_str());
    string command;
    ExpandCommand(edge, &command, err);
    printf("%s\n", command.c_str());
    if (!output.empty())
      printf("%s", output.c_str());
    if (output.empty() || output[output.size() - 1] != '\n')
      printf("\n");
    fflush(stdout);
    ++fail_count_;
    fail_code_ = exit_code;
    stopped_early_ = (config_.failures_allowed != 0 &&
                      fail_count_ >= config_.failures_allowed);
    status_->BuildFinished(edge, exit_code, string(), false);
    // Mark the outputs as ready so the build can continue.
    edge->outputs_ready_ = true;
    plan_.EdgeFinished(edge, err);
    return true;
  }

  // Restat the outputs.
  int64_t start_time_ns = GetTimeNanos();
  bool outputs_changed = false;
  for (size_t i = 0; i < edge->outputs_.size(); ++i) {
    Node* out = edge->outputs_[i];
    int64_t new_mtime = disk_->Stat(out->path(), err);
    if (new_mtime < 0)
      return false;
    if (new_mtime != out->mtime_)
      outputs_changed = true;
    out->set_mtime(new_mtime);
  }
  // Process the depfile and record the deps.
  if (!ProcessDepfile(edge, output, err))
    return false;

  // Record the command in the build log.
  if (log_ && !edge->is_phony_) {
    int end_time = (int)(GetTimeMillis() - start_time_);
    int start_time = (int)(edge->start_time_ms_);
    int64_t restat_mtime = start_time_ns;
    if (edge->restat_) {
      int64_t post = edge->outputs_.empty() ? 0 : edge->outputs_[0]->mtime_;
      if (post > restat_mtime)
        restat_mtime = post;
    }
    string command;
    ExpandCommand(edge, &command, err);
    log_->RecordCommand(edge, start_time, end_time, restat_mtime,
                        HashString(command));
  }

  // Print the output and the status line.
  status_->BuildFinished(edge, exit_code, edge->filtered_output_.empty()
                                             ? output
                                             : edge->filtered_output_,
                         true);

  // Load dynamic dependencies.
  if (!LoadDyndeps(edge, err))
    return false;

  // Mark the outputs as ready and recompute the dirty state of dependents.
  edge->outputs_ready_ = true;
  plan_.EdgeFinished(edge, err);
  // Recompute dirty state of the outputs (for restat semantics).
  for (size_t i = 0; i < edge->outputs_.size(); ++i) {
    Node* out = edge->outputs_[i];
    recompute_.RecomputeNode(out, err);
  }
  // With restat, if the outputs' mtimes did not change, the dependents do
  // not need to be built.
  if (edge->restat_ && !outputs_changed) {
    // Remove the dependents from the plan.
    for (size_t i = 0; i < edge->outputs_.size(); ++i) {
      Node* out = edge->outputs_[i];
      for (size_t j = 0; j < out->out_edges().size(); ++j) {
        Edge* depend = out->out_edges()[j];
        if (plan_.added_.count(depend)) {
          // Mark the dependents as not dirty and remove them from the plan.
          for (size_t k = 0; k < depend->outputs_.size(); ++k)
            depend->outputs_[k]->dirty_ = false;
        }
      }
    }
  }
  return true;
}

int Builder::Build(string* err) {
  status_->BuildStarted();
  int total = 0;
  for (set<Edge*>::iterator i = plan_.added_.begin(); i != plan_.added_.end();
       ++i)
    if (!(*i)->is_phony_)
      ++total;
  status_->SetTotalEdges(total);
  while (plan_.more_to_do()) {
    // Start as many edges as we can.
    for (;;) {
      if (plan_.outstanding() >= config_.parallelism)
        break;
      if (config_.failures_allowed != 0 &&
          fail_count_ >= config_.failures_allowed)
        break;
      if (config_.max_load_average > 0.0 &&
          GetLoadAverage() > config_.max_load_average)
        break;
      Edge* edge = plan_.FindNextEdgeToExecute();
      if (!edge)
        break;
      // Check the pool depth.
      if (edge->pool_) {
        if (!CanStartInPool(edge)) {
          // Put the edge back and try another one.
          plan_.ready_.insert(edge);
          Edge* other = plan_.FindNextEdgeToExecute();
          if (!other || other == edge) {
            plan_.ready_.insert(edge);
            break;
          }
          edge = other;
        }
      }
      if (!edge->deps_type_ == Edge::kNoDeps) {
        // Validate the deps type.
      }
      if (edge->deps_type_ != Edge::kNoDeps) {
        const EvalString* deps = edge->GetBinding("deps");
        string deps_val;
        if (deps) {
          if (!deps->EvaluateRaw(edge->env_, &deps_val, err))
            return 1;
          if (deps_val != "gcc" && deps_val != "msvc")
            Fatal("unknown deps type '%s'", deps_val.c_str());
        }
      }
      Subprocess* subproc = NULL;
      if (!StartEdge(edge, &subproc, err)) {
        Error("%s", err->c_str());
        return 1;
      }
      if (subproc)
        continue;
    }
    if (!subprocs_.more_pending()) {
      if (plan_.outstanding() == 0)
        break;
      continue;
    }
    if (!subprocs_.DoWork()) {
      *err = "select: " + string(strerror(errno));
      return 1;
    }
    Subprocess* subproc;
    while ((subproc = subprocs_.NextFinished()) != NULL) {
      Edge* edge = running_[subproc];
      if (!FinishCommand(edge, subproc, err)) {
        // Interrupted.
        return 130;
      }
    }
  }
  // Determine the exit code and error message.
  if (!plan_.more_to_do() || plan_.outstanding() == 0) {
    if (fail_count_ > 0) {
      if (stopped_early_) {
        if (config_.failures_allowed == 1)
          *err = "build stopped: subcommand failed.";
        else
          *err = "build stopped: subcommands failed.";
      } else {
        *err = "build stopped: cannot make progress due to previous errors.";
      }
      return fail_code_;
    }
  }
  return 0;
}
