  for (size_t i = 0; i < edge->inputs_.size(); ++i) {
    Node* input = edge->inputs_[i];
    out->push_back(input);
    CollectInputs(input, out);
  }
  for (size_t i = 0; i < edge->order_only_deps_.size(); ++i) {
    Node* input = edge->order_only_deps_[i];
    out->push_back(input);
    CollectInputs(input, out);
  }
}

int CommandsTool(const vector<string>& args) {
  bool single = false;
  vector<string> targets;
  for (size_t i = 0; i < args.size(); ++i) {
    if (args[i] == "-s") {
      single = true;
    } else if (args[i] == "-h" || args[i] == "--help") {
      printf("usage: ninja -t commands [options] [targets]\n\n");
      printf("options:\n");
      printf("  -s     only print the final command, not the chain\n");
      return 1;
    } else {
      targets.push_back(args[i]);
    }
  }
  vector<Node*> roots;
  if (targets.empty()) {
    roots = g_state->default_targets_;
  } else {
    for (size_t i = 0; i < targets.size(); ++i) {
      Node* node = g_state->LookupNode(targets[i]);
      if (!node) {
        Error("unknown target '%s'", targets[i].c_str());
        return 1;
      }
      roots.push_back(node);
    }
  }
  // Walk the graph in post-order, printing the commands.
  set<Node*> visited;
  vector<Edge*> order;
  // Recursive DFS.
  // (Use an explicit stack to avoid deep recursion.)
  vector<pair<Node*, int> > stack;
  for (size_t i = 0; i < roots.size(); ++i)
    stack.push_back(make_pair(roots[i], 0));
  while (!stack.empty()) {
    Node* node = stack.back().first;
    int phase = stack.back().second;
    stack.pop_back();
    if (phase == 1) {
      if (node->in_edge())
        order.push_back(node->in_edge());
      continue;
    }
    if (visited.count(node))
      continue;
    visited.insert(node);
    Edge* edge = node->in_edge();
    if (!edge)
      continue;
    stack.push_back(make_pair(node, 1));
    for (size_t i = 0; i < edge->inputs_.size(); ++i)
      stack.push_back(make_pair(edge->inputs_[i], 0));
    for (size_t i = 0; i < edge->order_only_deps_.size(); ++i)
      stack.push_back(make_pair(edge->order_only_deps_[i], 0));
  }
  vector<string> commands;
  for (size_t i = 0; i < order.size(); ++i) {
    Edge* edge = order[i];
    if (edge->is_phony_)
      continue;
    string command;
    string err;
    if (!edge->EvaluateCommand(false, &command, &err))
      continue;
    commands.push_back(command);
  }
  if (single) {
    if (!commands.empty())
      printf("%s\n", commands.back().c_str());
  } else {
    for (size_t i = 0; i < commands.size(); ++i)
      printf("%s\n", commands[i].c_str());
  }
  return 0;
}

int InputsTool(const vector<string>& args) {
  bool print0 = false;
  bool escape = true;
  bool dep_order = false;
  vector<string> targets;
  for (size_t i = 0; i < args.size(); ++i) {
    const string& a = args[i];
    if (a == "-h" || a == "--help") {
      printf("Usage '-t inputs [options] [targets]\n\n");
      printf("List all inputs used for a set of targets, sorted in dependency order.\n");
      printf("Note that by default, results are shell escaped, and sorted alphabetically,\n");
      printf("and never include validation target paths.\n\n");
      printf("Options:\n");
      printf("  -h, --help          Print this message.\n");
      printf("  -0, --print0            Use \\0, instead of \\n as a line terminator.\n");
      printf("  -E, --no-shell-escape   Do not shell escape the result.\n");
      printf("  -d, --dependency-order  Sort results by dependency order.\n");
      return 1;
    } else if (a == "-0" || a == "--print0") {
      print0 = true;
    } else if (a == "-E" || a == "--no-shell-escape") {
      escape = false;
    } else if (a == "-d" || a == "--dependency-order") {
      dep_order = true;
    } else {
      targets.push_back(a);
    }
  }
  vector<Node*> roots;
  if (targets.empty()) {
    roots = g_state->default_targets_;
  } else {
    for (size_t i = 0; i < targets.size(); ++i) {
      Node* node = g_state->LookupNode(targets[i]);
      if (!node) {
        Error("unknown target '%s'", targets[i].c_str());
        return 1;
      }
      roots.push_back(node);
    }
  }
  vector<Node*> inputs;
  for (size_t i = 0; i < roots.size(); ++i)
    CollectInputs(roots[i], &inputs);
  if (dep_order) {
    for (size_t i = 0; i < inputs.size(); ++i) {
      string p = inputs[i]->path();
      printf("%s%c", escape ? ShellEscape(p).c_str() : p.c_str(),
             print0 ? '\0' : '\n');
    }
  } else {
    set<string> sorted;
    for (size_t i = 0; i < inputs.size(); ++i) {
      string p = inputs[i]->path();
      sorted.insert(escape ? ShellEscape(p) : p);
    }
    for (set<string>::iterator i = sorted.begin(); i != sorted.end(); ++i)
      printf("%s%c", i->c_str(), print0 ? '\0' : '\n');
  }
  return 0;
}

int MultiInputsTool(const vector<string>& args) {
  string delim = "\t";
  bool print0 = false;
  vector<string> targets;
  for (size_t i = 0; i < args.size(); ++i) {
    const string& a = args[i];
    if (a == "-h" || a == "--help") {
      printf("Usage '-t multi-inputs [options] [targets]\n\n");
      printf("Print one or more sets of inputs required to build targets, sorted in dependency order.\n");
      printf("The tool works like inputs tool but with addition of the target for each line.\n");
      printf("The output will be a series of lines with the following elements:\n");
      printf("<target> <delimiter> <input> <terminator>\n");
      printf("Note that a given input may appear for several targets if it is used by more than one targets.\n");
      printf("Options:\n");
      printf("  -h, --help                   Print this message.\n");
      printf("  -d  --delimiter=DELIM        Use DELIM instead of TAB for field delimiter.\n");
      printf("  -0, --print0                 Use \\0, instead of \\n as a line terminator.\n");
      return 1;
    } else if (a == "-0" || a == "--print0") {
      print0 = true;
    } else if (a == "-d" || a.compare(0, 3, "-d=") == 0) {
      delim = a.substr(3);
    } else if (a == "--delimiter") {
      if (i + 1 < args.size())
        delim = args[++i];
    } else if (a.compare(0, 12, "--delimiter=") == 0) {
      delim = a.substr(12);
    } else {
      targets.push_back(a);
    }
  }
  vector<Node*> roots;
  if (targets.empty()) {
    roots = g_state->default_targets_;
  } else {
    for (size_t i = 0; i < targets.size(); ++i) {
      Node* node = g_state->LookupNode(targets[i]);
      if (!node) {
        Error("unknown target '%s'", targets[i].c_str());
        return 1;
      }
      roots.push_back(node);
    }
  }
  for (size_t i = 0; i < roots.size(); ++i) {
    vector<Node*> inputs;
    CollectInputs(roots[i], &inputs);
    set<string> sorted;
    for (size_t j = 0; j < inputs.size(); ++j)
      sorted.insert(inputs[j]->path());
    for (set<string>::iterator j = sorted.begin(); j != sorted.end(); ++j)
      printf("%s%s%s%c", roots[i]->path().c_str(), delim.c_str(), j->c_str(),
             print0 ? '\0' : '\n');
  }
  return 0;
}
