    Error("expected a target to query");
    return 1;
  }
  for (size_t i = 0; i < args.size(); ++i) {
    Node* node = g_state->LookupNode(args[i]);
    if (!node) {
      Error("unknown target '%s'", args[i].c_str());
      return 1;
    }
    printf("%s:\n", node->path().c_str());
    if (node->in_edge()) {
      Edge* edge = node->in_edge();
      printf("  input: %s\n", edge->rule_->name().c_str());
      for (size_t j = 0; j < edge->inputs_.size(); ++j) {
        Node* input = edge->inputs_[j];
        const char* prefix = "    ";
        if (j >= edge->explicit_input_count_) {
          if (j >= edge->explicit_input_count_ + edge->implicit_input_count_)
            prefix = "    || ";
          else
            prefix = "    | ";
        }
        printf("%s%s\n", prefix, input->path().c_str());
      }
    }
    printf("  outputs:\n");
    for (size_t j = 0; j < node->out_edges().size(); ++j) {
      Edge* edge = node->out_edges()[j];
      // Only print the edges where this node is an explicit output.
      bool explicit_out = false;
      for (size_t k = 0; k < edge->outputs_.size(); ++k)
        if (edge->outputs_[k] == node)
          explicit_out = true;
      if (explicit_out)
        printf("    %s\n", edge->outputs_[0]->path().c_str());
      else
        printf("    %s\n", edge->outputs_[0]->path().c_str());
    }
    // Validations.
    bool printed = false;
    for (size_t j = 0; j < node->out_edges().size(); ++j) {
      Edge* edge = node->out_edges()[j];
      for (size_t k = 0; k < edge->validations_.size(); ++k) {
        if (!printed) {
          printf("  validation for:\n");
          printed = true;
        }
        printf("    %s\n", edge->outputs_[0]->path().c_str());
      }
    }
  }
  return 0;
}
