int MissingDepsTool(const vector<string>& args) {
  // Process the nodes.
  set<Node*> processed;
  int count = 0;
  // Walk the graph from the roots.
  vector<Node*> stack;
  for (size_t i = 0; i < g_state->default_targets_.size(); ++i)
    stack.push_back(g_state->default_targets_[i]);
  if (stack.empty()) {
    for (size_t i = 0; i < g_state->nodes_.size(); ++i)
      stack.push_back(g_state->nodes_[i]);
  }
  set<Node*> generated;
  for (size_t i = 0; i < g_state->edges_.size(); ++i) {
    Edge* edge = g_state->edges_[i];
    for (size_t j = 0; j < edge->outputs_.size(); ++j)
      generated.insert(edge->outputs_[j]);
  }
  while (!stack.empty()) {
    Node* node = stack.back();
    stack.pop_back();
    if (processed.count(node))
      continue;
    processed.insert(node);
    ++count;
    Edge* edge = node->in_edge();
    if (edge) {
      for (size_t j = 0; j < edge->inputs_.size(); ++j)
        stack.push_back(edge->inputs_[j]);
      for (size_t j = 0; j < edge->order_only_deps_.size(); ++j)
        stack.push_back(edge->order_only_deps_[j]);
      for (size_t j = 0; j < edge->validations_.size(); ++j)
        stack.push_back(edge->validations_[j]);
    }
  }
  printf("Processed %d nodes.\n", count);
  // Find targets that depend on generated files without a path to the
  // generator.
  bool found = false;
  for (set<Node*>::iterator i = processed.begin(); i != processed.end(); ++i) {
    Node* node = *i;
    Edge* edge = node->in_edge();
    if (!edge)
      continue;
    for (size_t j = 0; j < edge->inputs_.size(); ++j) {
      Node* input = edge->inputs_[j];
      if (!generated.count(input))
        continue;
      // Check for an explicit/order-only path to the generator.
      if (HasPathTo(edge, input))
        continue;
      if (!found) {
        printf("missing dependencies on generated files:\n");
        found = true;
      }
      printf("    %s -> %s\n", node->path().c_str(), input->path().c_str());
    }
  }
  if (!found)
    printf("No missing dependencies on generated files found.\n");
  return 0;
}

bool HasPathTo(Edge* from, Node* to) {
  // BFS over explicit and order-only deps.
  set<Edge*> visited;
  vector<Edge*> queue;
  queue.push_back(from);
  while (!queue.empty()) {
    Edge* edge = queue.back();
    queue.pop_back();
    if (visited.count(edge))
      continue;
    visited.insert(edge);
    for (size_t i = 0; i < edge->inputs_.size(); ++i) {
      Node* input = edge->inputs_[i];
      if (input == to)
        return true;
      if (input->in_edge())
        queue.push_back(input->in_edge());
    }
    for (size_t i = 0; i < edge->order_only_deps_.size(); ++i) {
      Node* input = edge->order_only_deps_[i];
      if (input == to)
        return true;
      if (input->in_edge())
        queue.push_back(input->in_edge());
    }
  }
  return false;
}

