      if (node->out_edges().empty())
        roots.push_back(node);
    }
    PrintTargetsByDepth(roots, depth, 0);
    return 0;
  }
  Error("unknown target tool mode '%s'", args[0].c_str());
  return 1;
}

void PrintTargetsByDepth(const vector<Node*>& roots, int depth, int indent) {
  for (size_t i = 0; i < roots.size(); ++i) {
    Node* node = roots[i];
    printf("%*s%s: %s\n", indent, "", node->path().c_str(),
           node->in_edge() ? node->in_edge()->rule_->name().c_str() : "");
    if (depth == 0 || depth > 1) {
      vector<Node*> inputs;
      if (node->in_edge()) {
        for (size_t j = 0; j < node->in_edge()->inputs_.size(); ++j)
          inputs.push_back(node->in_edge()->inputs_[j]);
      }
      if (!inputs.empty())
        PrintTargetsByDepth(inputs, depth == 0 ? 0 : depth - 1, indent + 2);
    }
  }
}

static void JsonEscape(const string& in, string* out) {
  for (size_t i = 0; i < in.size(); ++i) {
    char c = in[i];
    switch (c) {
      case '"': *out += "\\\""; break;
      case '\\': *out += "\\\\"; break;
      case '\n': *out += "\\n"; break;
      case '\r': *out += "\\r"; break;
      case '\t': *out += "\\t"; break;
      default:
        if ((unsigned char)c < 0x20) {
          char buf[8];
          snprintf(buf, sizeof(buf), "\\u%04x", c);
          *out += buf;
        } else {
          out->push_back(c);
        }
    }
  }
}

static void PrintCompdbEntry(const vector<Edge*>& edges, bool expand_rsp) {
  printf("[\n");
  bool first = true;
  string cwd = GetCwd();
  for (size_t i = 0; i < edges.size(); ++i) {
    Edge* edge = edges[i];
    string command;
    string err;
    if (!edge->EvaluateCommand(expand_rsp, &command, &err))
      continue;
    for (size_t j = 0; j < edge->inputs_.size(); ++j) {
      Node* input = edge->inputs_[j];
      string output = edge->outputs_.empty() ? "" : edge->outputs_[0]->path();
      if (!first)
        printf(",\n");
      first = false;
      printf("  {\n");
      printf("    \"directory\": \"");
      string dir;
      JsonEscape(cwd, &dir);
      printf("%s", dir.c_str());
      printf("\",\n");
      string cmd;
      JsonEscape(command, &cmd);
      printf("    \"command\": \"%s\",\n", cmd.c_str());
      string file;
      JsonEscape(input->path(), &file);
      printf("    \"file\": \"%s\",\n", file.c_str());
      string outj;
      JsonEscape(output, &outj);
      printf("    \"output\": \"%s\"\n", outj.c_str());
      printf("  }");
    }
  }
  printf("\n]\n");
}

int CompdbTool(const vector<string>& args, bool targets_mode) {
  bool expand_rsp = false;
  vector<string> names;
  for (size_t i = 0; i < args.size(); ++i) {
    if (args[i] == "-x") {
      expand_rsp = true;
    } else if (args[i] == "-h" || args[i] == "--help") {
      printf("usage: ninja -t compdb [options] [rules]\n\n");
      printf("options:\n");
      printf("  -x     expand @rspfile style response file invocations\n");
      return 1;
    } else {
      names.push_back(args[i]);
    }
  }
  vector<Edge*> edges;
  for (size_t i = 0; i < g_state->edges_.size(); ++i) {
    Edge* edge = g_state->edges_[i];
    if (edge->is_phony_)
      continue;
    if (!names.empty()) {
      bool match = false;
      for (size_t j = 0; j < names.size(); ++j)
        if (edge->rule_->name() == names[j])
          match = true;
      if (!match)
        continue;
    }
    edges.push_back(edge);
  }
  PrintCompdbEntry(edges, expand_rsp);
  return 0;
}

int CleanTool(const vector<string>& args) {
  bool generator = false;
  bool rules_mode = false;
  vector<string> targets;
  for (size_t i = 0; i < args.size(); ++i) {
    if (args[i] == "-g") {
      generator = true;
    } else if (args[i] == "-r") {
      rules_mode = true;
    } else if (args[i] == "-h" || args[i] == "--help") {
      printf("usage: ninja -t clean [options] [targets]\n\n");
      printf("options:\n");
      printf("  -g     also clean files marked as ninja generator output\n");
      printf("  -r     interpret targets as a list of rules to clean instead\n");
      return 1;
    } else {
      targets.push_back(args[i]);
    }
  }
  set<Node*> clean;
  if (targets.empty()) {
    for (size_t i = 0; i < g_state->edges_.size(); ++i) {
      Edge* edge = g_state->edges_[i];
      if (edge->is_phony_)
        continue;
      if (edge->is_generator_ && !generator)
        continue;
      for (size_t j = 0; j < edge->outputs_.size(); ++j)
        clean.insert(edge->outputs_[j]);
      for (size_t j = 0; j < edge->implicit_outs_.size(); ++j)
        clean.insert(edge->implicit_outs_[j]);
    }
  } else if (rules_mode) {
    for (size_t i = 0; i < g_state->edges_.size(); ++i) {
      Edge* edge = g_state->edges_[i];
      if (edge->is_phony_)
        continue;
      bool match = false;
      for (size_t j = 0; j < targets.size(); ++j)
        if (edge->rule_->name() == targets[j])
          match = true;
      if (!match)
        continue;
      for (size_t j = 0; j < edge->outputs_.size(); ++j)
        clean.insert(edge->outputs_[j]);
      for (size_t j = 0; j < edge->implicit_outs_.size(); ++j)
        clean.insert(edge->implicit_outs_[j]);
    }
  } else {
    for (size_t i = 0; i < targets.size(); ++i) {
      Node* node = g_state->LookupNode(targets[i]);
      if (!node) {
        Error("unknown target '%s'", targets[i].c_str());
        continue;
      }
      CollectCleanTargets(node, &clean);
    }
  }
  vector<string> removed;
  for (set<Node*>::iterator i = clean.begin(); i != clean.end(); ++i) {
    const string& path = (*i)->path();
    if (g_dry_run) {
      // Nothing to do.
    } else if (remove(path.c_str()) == 0) {
      // Removed.
    } else if (errno == ENOENT) {
      continue;
    } else {
      continue;
    }
    removed.push_back(path);
  }
  if (g_verbosity > 0 || g_dry_run) {
    printf("Cleaning...\n");
    for (size_t i = 0; i < removed.size(); ++i)
      printf("Remove %s\n", removed[i].c_str());
    printf("%d files.\n", (int)removed.size());
  } else {
    printf("Cleaning... %d files.\n", (int)removed.size());
  }
  return 0;
}

void CollectCleanTargets(Node* node, set<Node*>* clean) {
  Edge* edge = node->in_edge();
  if (edge) {
    for (size_t i = 0; i < edge->outputs_.size(); ++i)
      clean->insert(edge->outputs_[i]);
    for (size_t i = 0; i < edge->implicit_outs_.size(); ++i)
      clean->insert(edge->implicit_outs_[i]);
    for (size_t i = 0; i < edge->inputs_.size(); ++i)
      CollectCleanTargets(edge->inputs_[i], clean);
    for (size_t i = 0; i < edge->order_only_deps_.size(); ++i)
      CollectCleanTargets(edge->order_only_deps_[i], clean);
  }
}

int CleanDeadTool(const vector<string>& args) {
  set<string> outputs;
  for (size_t i = 0; i < g_state->edges_.size(); ++i) {
    Edge* edge = g_state->edges_[i];
    for (size_t j = 0; j < edge->outputs_.size(); ++j)
      outputs.insert(edge->outputs_[j]->path());
    for (size_t j = 0; j < edge->implicit_outs_.size(); ++j)
      outputs.insert(edge->implicit_outs_[j]->path());
  }
  vector<string> removed;
  if (g_build_log) {
    for (map<string, BuildLogEntry>::iterator i =
             g_build_log->entries_.begin();
         i != g_build_log->entries_.end(); ++i) {
      if (outputs.count(i->first))
        continue;
      if (!g_dry_run) {
        if (remove(i->first.c_str()) < 0)
          continue;
      }
      removed.push_back(i->first);
    }
  }
  if (g_verbosity > 0 || g_dry_run) {
    printf("Cleaning...\n");
    for (size_t i = 0; i < removed.size(); ++i)
      printf("Remove %s\n", removed[i].c_str());
    printf("%d files.\n", (int)removed.size());
  } else {
    printf("Cleaning... %d files.\n", (int)removed.size());
  }
  return 0;
}

int RulesTool(const vector<string>& args) {
  bool desc = false;
  for (size_t i = 0; i < args.size(); ++i) {
    if (args[i] == "-d")
      desc = true;
  }
  vector<Rule*> rules = g_state->rules_;
  sort(rules.begin(), rules.end(), RuleNameLess());
  for (size_t i = 0; i < rules.size(); ++i) {
    Rule* rule = rules[i];
    if (!desc) {
      printf("%s\n", rule->name().c_str());
    } else {
      const EvalString* d = rule->GetBinding("description");
      if (d && !d->empty())
        printf("%s: %s\n", rule->name().c_str(), d->Serialize().c_str());
      else
        printf("%s\n", rule->name().c_str());
    }
  }
  return 0;
}

int RestatTool(const vector<string>& args) {
  if (!g_build_log)
    return 0;
  // Re-stat all the outputs in the log.
  for (map<string, BuildLogEntry>::iterator i =
           g_build_log->entries_.begin();
       i != g_build_log->entries_.end(); ++i) {
    int64_t mtime = g_disk->Stat(i->first, NULL);
    if (mtime > 0)
      i->second.mtime = mtime;
  }
  // Rewrite the log.
  string path = g_disk->log_paths()[0];
  FILE* f = fopen(path.c_str(), "wb");
  if (!f)
    return 0;
  fputs(BuildLog::kFileSignature, f);
  for (map<string, BuildLogEntry>::iterator i =
           g_build_log->entries_.begin();
       i != g_build_log->entries_.end(); ++i) {
    fprintf(f, "0\t0\t%lld\t%s\t%llx\n", (long long)i->second.mtime,
            i->first.c_str(), (unsigned long long)i->second.hash);
  }
  fclose(f);
  return 0;
}

int RecompactTool(const vector<string>& args) {
  if (!g_deps_log)
    return 0;
  string path = g_disk->log_paths()[1];
  FILE* f = fopen(path.c_str(), "wb");
  if (!f)
    return 0;
  fputs(DepsLog::kFileSignature, f);
  unsigned int version = 4;
  fwrite(&version, 4, 1, f);
  map<string, int> ids;
  int next_id = 0;
  for (size_t i = 0; i < g_state->nodes_.size(); ++i) {
    Node* node = g_state->nodes_[i];
    const DepsLogDeps* deps = g_deps_log->GetDeps(node);
    if (!deps)
      continue;
    // Write the path records.
    if (!ids.count(node->path())) {
      int id = next_id++;
      ids[node->path()] = id;
      WritePathRecord(f, node->path(), id);
