#include "helpers.h"
#include "build_log.h"
#include "deps_log.h"
#include "util.h"

#include <stdio.h>
#include <unistd.h>

string GetCwd() {
  char buf[4096];
  if (getcwd(buf, sizeof(buf)) == NULL)
    return string();
  return string(buf);
}

void WritePathRecord(FILE* f, const string& path, int id) {
  size_t padded = (path.size() + 3) & ~3;
  unsigned int size = 4 + (unsigned int)padded;
  fwrite(&size, 4, 1, f);
  string p = path;
  p.resize(padded, '\0');
  fwrite(p.data(), padded, 1, f);
  unsigned int neg = (unsigned int)(~id);
  fwrite(&neg, 4, 1, f);
}
