cat >> main.cc <<'EOF'

int main(int argc, char** argv) {
  Options options;
  bool debug_keep_depfile = false;
  bool debug_keep_rsp = false;
  bool debug_explain = false;
  bool debug_stats = false;
  bool warn_phony_cycle = true;
  bool warn_phony_cycle_err = false;

  static const struct Option {
    const char* name;
    int has_arg;
    int val;
  } kLongOptions[] = {
    { "version", 0, 'V' },
    { "verbose", 0, 'v' },
    { "quiet", 0, 'q' },
    { "dry-run", 0, 'n' },
    { "help", 0, 'h' },
    { NULL, 0, 0 },
  };

  int opt;
  while ((opt = getopt_long(argc, argv, "C:f:j:k:l:nt:vd:w:",
                            kLongOptions, NULL)) != -1) {
    switch (opt) {
      case 'V':
        printf("%s\n", kVersion);
        return 0;
      case 'v':
        options.verbosity = BuildConfig::VERBOSE;
        break;
      case 'q':
        options.verbosity = BuildConfig::QUIET;
        break;
      case 'n':
        options.dry_run = true;
        break;
      case 'h':
        Usage();
        return 1;
      case 'C':
        options.chdir_path = optarg;
        break;
      case 'f':
        options.input_file = optarg;
        break;
      case 'j': {
        char* end;
        long value = strtol(optarg, &end, 10);
        if (*end != 0 || value < 0)
          Fatal("invalid -j parameter");
        options.parallelism = (int)value;
        break;
      }
      case 'k': {
        char* end;
        long value = strtol(optarg, &end, 10);
        if (*end != 0 || value < 0)
          Fatal("-k parameter not numeric; did you mean -k 0?");
        options.failures_allowed = (int)value;
        break;
      }
      case 'l': {
        char* end;
        double value = strtod(optarg, &end);
        if (*end != 0 || value < 0)
          Fatal("-l parameter not numeric: did you mean -l 0.0?");
        options.max_load_average = value;
        break;
      }
      case 'd':
        if (strcmp(optarg, "list") == 0) {
          printf("debugging modes:\n");
          printf("  stats        print operation counts/timing info\n");
          printf("  explain      explain what caused a command to execute\n");
          printf("  keepdepfile  don't delete depfiles after they're read by ninja\n");
          printf("  keeprsp      don't delete @response files on success\n");
          return 1;
        }
        if (strcmp(optarg, "explain") == 0) debug_explain = true;
        else if (strcmp(optarg, "keepdepfile") == 0) debug_keep_depfile = true;
        else if (strcmp(optarg, "keeprsp") == 0) debug_keep_rsp = true;
        else if (strcmp(optarg, "stats") == 0) debug_stats = true;
        else Fatal("unknown debug mode '%s'", optarg);
        break;
      case 'w':
        if (strcmp(optarg, "list") == 0) {
          printf("warning flags:\n");
          printf("phonycycle={err,warn}  phony build statement references itself\n");
          return 1;
        }
        if (strncmp(optarg, "phonycycle=", 11) == 0) {
          const char* value = optarg + 11;
          if (strcmp(value, "err") == 0) { warn_phony_cycle_err = true; warn_phony_cycle = false; }
          else if (strcmp(value, "warn") == 0) { warn_phony_cycle = true; warn_phony_cycle_err = false; }
          else Fatal("unknown phony-cycle mode '%s'", value);
        } else {
          Error("unknown warning flag '%s'", optarg);
          return 1;
        }
        break;
      case 't':
        options.tool = optarg;
        // Everything after this is passed to the tool.
        while (optind < argc)
          options.tool_args.push_back(argv[optind++]);
        break;
      default:
        Usage();
        return 1;
    }
  }
  for (int i = optind; i < argc; ++i)
    options.targets.push_back(argv[i]);

  g_ninja_command = argv[0];
  g_input_file = options.input_file;
  g_dry_run = options.dry_run;
  g_verbosity = (options.verbosity == BuildConfig::VERBOSE) ? 1 : 0;

  // Change directory if requested.
  if (!options.chdir_path.empty()) {
    printf("ninja: Entering directory `%s'\n", options.chdir_path.c_str());
    if (chdir(options.chdir_path.c_str()) < 0)
      Fatal("chdir to '%s' - %s", options.chdir_path.c_str(), strerror(errno));
  }

  // Set up the parallelism.
  BuildConfig config;
  config.verbosity = options.verbosity;
  config.dry_run = options.dry_run;
  config.explain = debug_explain;
  config.keep_depfile = debug_keep_depfile;
  config.keep_rsp = debug_keep_rsp;
  config.parallelism = (options.parallelism >= 0) ? options.parallelism
                                                 : DefaultParallelism();
  if (config.parallelism == 0)
    config.parallelism = 1 << 30;
  config.failures_allowed = (options.failures_allowed >= 0)
                                ? options.failures_allowed : 1;
  if (config.failures_allowed == 0)
    config.failures_allowed = 1 << 30;
  config.max_load_average = options.max_load_average;
  {
    const char* status = getenv("NINJA_STATUS");
    if (status)
      config.status_progress_format = status;
  }

  // Read the build file.
  string contents;
  string err;
  RealDiskInterface* disk = new RealDiskInterface;
  g_disk = disk;
  State* state = new State;
  g_state = state;

  ManifestParser parser(state, disk);
  parser.file_env_ = new Scope(NULL);
  parser.file_rules_ = new RuleScope;
  if (!ReadFile(options.input_file, &contents, &err)) {
    Error("loading '%s': %s", options.input_file.c_str(), err.c_str());
    return 1;
  }
  if (!parser.Parse(options.input_file, contents, &err, false)) {
    Error("%s", err.c_str());
    return 1;
  }

  // Run the tool if requested.
  if (!options.tool.empty()) {
    int result = RunTool(options.tool, options.tool_args, config, disk);
    return result;
  }

  // Load the logs.
  string builddir;
  const string* build_dir = parser.file_env_->LookupVariable("builddir");
  if (build_dir)
    builddir = *build_dir;
  if (!builddir.empty() && builddir[builddir.size() - 1] != '/')
    builddir += "/";
  string log_path = builddir + ".ninja_log";
  string deps_path = builddir + ".ninja_deps";
  vector<string> log_paths;
  log_paths.push_back(log_path);
  log_paths.push_back(deps_path);
  disk->set_logs(NULL, NULL, &log_paths);

  BuildLog* build_log = new BuildLog;
  if (!build_log->Load(log_path, &err)) {
    Error("%s", err.c_str());
    return 1;
  }
  DepsLog* deps_log = new DepsLog;
  if (!deps_log->Load(deps_path, state, &err)) {
    Error("%s", err.c_str());
    return 1;
  }
  disk->set_logs(build_log, deps_log, &log_paths);

  // Compute the dirty state and build.
  Builder builder(state, config, disk, NULL);
  builder.SetBuildLog(build_log);
  builder.SetDepsLog(deps_log);
  StatusPrinter status(&config);
  builder.status_ = &status;

  vector<string> targets = options.targets;
