        options.dry_run = true;
        break;
      case 'h':
        Usage();
        return 1;
      case 'C':
        options.chdir_path = optarg;
        break;
      case 'f':
        options.input_file = optarg;
        break;
      case 'j': {
        char* end;
        long value = strtol(optarg, &end, 10);
        if (*end != 0 || value < 0)
          Fatal("invalid -j parameter");
        options.parallelism = (int)value;
        break;
      }
      case 'k': {
        char* end;
