        double value = strtod(optarg, &end);
        if (*end != 0 || value < 0)
          Fatal("-l parameter not numeric: did you mean -l 0.0?");
        options.max_load_average = value;
        break;
      }
      case 'd':
        if (strcmp(optarg, "list") == 0) {
          printf("debugging modes:\n");
          printf("  stats        print operation counts/timing info\n");
          printf("  explain      explain what caused a command to execute\n");
          printf("  keepdepfile  don't delete depfiles after they're read by ninja\n");
          printf("  keeprsp      don't delete @response files on success\n");
          return 1;
        }
        if (strcmp(optarg, "explain") == 0) debug_explain = true;
        else if (strcmp(optarg, "keepdepfile") == 0) debug_keep_depfile = true;
        else if (strcmp(optarg, "keeprsp") == 0) debug_keep_rsp = true;
        else if (strcmp(optarg, "stats") == 0) debug_stats = true;
        else Fatal("unknown debug mode '%s'", optarg);
        break;
      case 'w':
        if (strcmp(optarg, "list") == 0) {
          printf("warning flags:\n");
          printf("phonycycle={err,warn}  phony build statement references itself\n");
          return 1;
        }
        if (strncmp(optarg, "phonycycle=", 11) == 0) {
          const char* value = optarg + 11;
          if (strcmp(value, "err") == 0) { warn_phony_cycle_err = true; warn_phony_cycle = false; }
          else if (strcmp(value, "warn") == 0) { warn_phony_cycle = true; warn_phony_cycle_err = false; }
          else Fatal("unknown phony-cycle mode '%s'", value);
        } else {
          Error("unknown warning flag '%s'", optarg);
          return 1;
        }
        break;
      case 't':
        options.tool = optarg;
        // Everything after this is passed to the tool.
        while (optind < argc)
          options.tool_args.push_back(argv[optind++]);
        break;
      default:
        Usage();
        return 1;
    }
  }
  for (int i = optind; i < argc; ++i)
    options.targets.push_back(argv[i]);

  g_ninja_command = argv[0];
  g_input_file = options.input_file;
  g_dry_run = options.dry_run;
  g_verbosity = (options.verbosity == BuildConfig::VERBOSE) ? 1 : 0;

