  RealDiskInterface* disk = new RealDiskInterface;
  g_disk = disk;
  State* state = new State;
  g_state = state;

  ManifestParser parser(state, disk);
  parser.file_env_ = new Scope(NULL);
  parser.file_rules_ = new RuleScope;
  if (!ReadFile(options.input_file, &contents, &err)) {
    Error("loading '%s': %s", options.input_file.c_str(), err.c_str());
    return 1;
  }
  if (!parser.Parse(options.input_file, contents, &err, false)) {
    Error("%s", err.c_str());
    return 1;
  }

  // Run the tool if requested.
  if (!options.tool.empty()) {
    int result = RunTool(options.tool, options.tool_args, config, disk);
    return result;
  }

