  string builddir;
  const string* build_dir = parser.file_env_->LookupVariable("builddir");
  if (build_dir)
    builddir = *build_dir;
  if (!builddir.empty() && builddir[builddir.size() - 1] != '/')
    builddir += "/";
  string log_path = builddir + ".ninja_log";
  string deps_path = builddir + ".ninja_deps";
  vector<string> log_paths;
  log_paths.push_back(log_path);
  log_paths.push_back(deps_path);
  disk->set_logs(NULL, NULL, &log_paths);

  BuildLog* build_log = new BuildLog;
  if (!build_log->Load(log_path, &err)) {
    Error("%s", err.c_str());
    return 1;
  }
  DepsLog* deps_log = new DepsLog;
  if (!deps_log->Load(deps_path, state, &err)) {
    Error("%s", err.c_str());
    return 1;
  }
  disk->set_logs(build_log, deps_log, &log_paths);

  // Compute the dirty state and build.
  Builder builder(state, config, disk, NULL);
  builder.SetBuildLog(build_log);
  builder.SetDepsLog(deps_log);
  StatusPrinter status(&config);
  builder.status_ = &status;

