bool DyndepParser::ExpectToken(Lexer::Token token, const char* expected,
                               string* err) {
  Lexer::Token t = lexer_.ReadToken();
  if (t == token)
    return true;
  if (t == Lexer::EOF_TOKEN) {
    lexer_.Error("unexpected EOF", err);
    return false;
  }
  lexer_.Error(StringPrintf("expected %s, got %s", expected,
                            lexer_.TokenName(t)), err);
  return false;
}

bool DyndepParser::ParseBuild(string* err) {
  vector<string> outs, implicit_outs;
  if (!ParsePaths(&outs, &implicit_outs, true, err))
    return false;
  if (outs.size() != 1) {
    lexer_.Error("expected one explicit output", err);
    return false;
  }
  const char* rule_pos = lexer_.GetPos();
  string rule_name;
  if (!lexer_.ReadIdent(&rule_name)) {
    lexer_.Error("expected build command name", err);
    return false;
  }
  if (rule_name != "dyndep") {
    const char* save = lexer_.GetPos();
    lexer_.SetPos(rule_pos);
    lexer_.Error("unknown build rule '" + rule_name + "'", err);
    lexer_.SetPos(save);
    return false;
  }
  vector<string> implicit_ins;
  if (!ParsePaths(&implicit_ins, NULL, false, err))
    return false;
  if (!ExpectToken(Lexer::NEWLINE, "newline", err))
    return false;
  bool restat = false;
  while (lexer_.PeekToken(Lexer::INDENT)) {
    lexer_.ReadToken();
    string key, val;
    if (!ParseLet(&key, &val, err))
      return false;
    if (key != "restat") {
      lexer_.Error("unexpected variable '" + key + "'", err);
      return false;
    }
    restat = !val.empty();
  }
  // Now apply the dyndep information to the manifest edge.
  Node* out = state_->GetNode(outs[0]);
  Edge* edge = out->in_edge();
  if (!edge) {
    lexer_.ErrorNoContext("the dyndep file references an unknown output '" +
                              outs[0] + "'", err);
    return false;
  }
  if (dyndep_edges_.count(edge)) {
    lexer_.ErrorNoContext("multiple dyndep build statements for '" +
                              outs[0] + "'", err);
    return false;
  }
  dyndep_edges_.insert(edge);
  for (size_t i = 0; i < implicit_outs.size(); ++i) {
    Node* node = state_->GetNode(implicit_outs[i]);
    edge->implicit_outs_.push_back(node);
    node->set_in_edge(edge);
    // Add the implicit output as an input of the edges that use it.
    for (size_t j = 0; j < implicit_ins.size(); ++j) {
      if (implicit_ins[j] == node->path())
        continue;
    }
  }
  for (size_t i = 0; i < implicit_ins.size(); ++i) {
    Node* node = state_->GetNode(implicit_ins[i]);
    edge->inputs_.push_back(node);
    node->AddOutEdge(edge);
  }
  edge->explicit_input_count_ = (int)edge->inputs_.size();
  edge->implicit_input_count_ = (int)edge->inputs_.size();
  if (restat)
    edge->restat_ = true;
  return true;
}

bool DyndepParser::ParsePaths(vector<string>* out, vector<string>* implicit,
                              bool stop_at_colon, string* err) {
  PathList list;
  int section = 0;
  for (;;) {
    const char* p = lexer_.GetPos();
    if (*p == '\0') {
      lexer_.Error("unexpected EOF", err);
      return false;
    }
    if (*p == '\n') {
      if (stop_at_colon) {
        lexer_.Error("expected ':', got newline ($ also escapes ':')", err);
        return false;
      }
      return true;
    }
    if (stop_at_colon && *p == ':') {
      lexer_.SetPos(p + 1);
      return true;
    }
    if (*p == ' ') {
      lexer_.SetPos(p + 1);
      continue;
    }
    if (*p == '|') {
      if (p[1] == '|') {
        lexer_.SetPos(p + 2);
        section = 2;
        continue;
      }
      lexer_.SetPos(p + 1);
      section = 1;
      continue;
    }
    string path;
    if (!lexer_.ReadPath(&path, err))
      return false;
    if (path.empty()) {
      lexer_.Error("expected path", err);
      return false;
    }
    CanonicalizePath(&path);
    if (section == 0)
      out->push_back(path);
    else if (implicit)
      implicit->push_back(path);
  }
}
