{"command": "cd /tmp/src && cat >> status.cc <<'EOF'

void StatusPrinter::BuildEdgeStarted(const Edge* edge) {
  ++started_edges_;
  if (edge->rule_ && edge->rule_->name() == "phony")
    return;
  bool is_console = edge->pool_ && edge->pool_->name() == "console";
  if (is_console) {
    PrintStatus(edge, true);
  }
}

void StatusPrinter::BuildFinished(const Edge* edge, int exit_code,
                                  const string& output, bool success) {
  ++finished_edges_;
  if (edge->rule_ && edge->rule_->name() == "phony")
    return;
  bool is_console = edge->pool_ && edge->pool_->name() == "console";
  if (is_console) {
    // The status was already printed when the edge started.
    printed_line_ = true;
