#include "lexer.h"
#include "util.h"

#include <ctype.h>
#include <string.h>

void Lexer::Start(const string& filename, const string& input) {
  input_ = input.data();
  pos_ = input.data();
  end_ = input.data() + input.size();
  filename_ = filename;
}

int Lexer::LineFor(const char* pos) const {
  int line = 1;
  for (const char* p = input_; p < pos; ++p)
    if (*p == '\n')
      ++line;
  return line;
}

const char* Lexer::LineStartFor(const char* pos) const {
  const char* p = pos;
  while (p > input_ && p[-1] != '\n')
    --p;
  return p;
}

bool Lexer::AtLineStart() const {
  return pos_ == input_ || pos_[-1] == '\n';
}

bool Lexer::Error(const string& message, string* err) {
  const char* line_start = LineStartFor(pos_);
  const char* line_end = pos_;
  while (line_end < end_ && *line_end != '\n')
    ++line_end;
  string line_text(line_start, line_end);
  int col = (int)(pos_ - line_start);
  string caret;
  for (int i = 0; i < col; ++i)
    caret.push_back(' ');
  *err = StringPrintf("%s:%d: %s\n%s\n%s^ near here", filename_.c_str(),
                      LineFor(pos_), message.c_str(), line_text.c_str(),
                      caret.c_str());
  return false;
}

bool Lexer::ErrorNoContext(const string& message, string* err) {
  *err = StringPrintf("%s:%d: %s\n", filename_.c_str(), LineFor(pos_),
                      message.c_str());
  return false;
}

const char* Lexer::TokenName(Token token) const {
  switch (token) {
    case NEWLINE: return "newline";
    case INDENT: return "indent";
    case IDENT: return "identifier";
    case COLON: return "':'";
    case PIPE: return "'|'";
    case PIPE2: return "'||'";
    case PIPEAT: return "'|@'";
    case EQUALS: return "'='";
    case RULE: return "identifier";
    case BUILD: return "identifier";
    case POOL: return "identifier";
    case DEFAULT: return "identifier";
    case SUBNINJA: return "identifier";
    case INCLUDE: return "identifier";
    case EOF_TOKEN: return "eof";
    default: return "lexing error";
  }
}

Lexer::Token Lexer::ReadToken() {
  for (;;) {
    if (pos_ >= end_)
      return EOF_TOKEN;
    // At the beginning of a line, leading whitespace introduces an
    // indentation token.
    if (AtLineStart() && *pos_ == ' ') {
      const char* p = pos_;
      while (p < end_ && (*p == ' ' || *p == '\t'))
        ++p;
      if (p < end_ && *p == '\n') {
        // A blank line: not an indent.
        pos_ = p;
        continue;
      }
      if (p < end_ && *p == '#') {
        // A comment line: skip it entirely, including the newline.
        while (p < end_ && *p != '\n')
          ++p;
        if (p < end_)
          ++p;
        pos_ = p;
